insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('gemma','gemma','Google — Gemma','model','משפחת מודלים במשקלים זמינים של Google, נפרדת משירות Gemini API. לומדים לבחור checkpoint, פורמט וסביבת הרצה ולבדוק את הרישיון המדויק; תנאי Gemma אינם אחידים לכל דורות המשפחה.','published','verified','2026-11-03',1,'מחקר 07/08 מאושר; דוגמאות ותרגילים מוצעים שלא הורצו. אין טענת SDK, רישוי או ביצועים מעבר למקורות.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved models07-20261103-v1 M07-01–M07-18 and inference08-20261103-v1 I08-01–I08-09 with overrides; docs/DECISIONS.md D-037');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('microsoft-phi','microsoft-phi','Microsoft — Phi','model','משפחת מודלים קטנים של Microsoft להשוואת התאמה למשימות ממוקדות ולהרצה לפי חומרה. Phi היא משקלי מודל, לא Microsoft Foundry ולא ONNX Runtime; רישוי ואיכות נבדקים לפי checkpoint.','published','verified','2026-11-03',1,'מחקר 07/08 מאושר; דוגמאות ותרגילים מוצעים שלא הורצו. אין טענת SDK, רישוי או ביצועים מעבר למקורות.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved models07-20261103-v1 M07-01–M07-18 and inference08-20261103-v1 I08-01–I08-09 with overrides; docs/DECISIONS.md D-037');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('cohere-command','cohere-command','Cohere — Command','model','משפחת מודלי generation של Cohere, להיכרות עם שימוש ארגוני ותשובות מבוססות ידע. יש להבחין Command ממוצרי Embed ו־Rerank, ובין רישיון checkpoint להיתר שימוש בשירות מסחרי.','published','verified','2026-11-03',1,'מחקר 07/08 מאושר; דוגמאות ותרגילים מוצעים שלא הורצו. אין טענת SDK, רישוי או ביצועים מעבר למקורות.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved models07-20261103-v1 M07-01–M07-18 and inference08-20261103-v1 I08-01–I08-09 with overrides; docs/DECISIONS.md D-037');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('inference-fundamentals','inference-fundamentals','הסקה מקומית והגשת מודלים — יסודות','concept','פרק בסיס לבחירה בין הסקה בתוך תהליך, שרת מקומי, שרת serving ו־gateway. לומדים פורמט וכימות, זיכרון ו־KV cache, עומס, נתיב מידע ובדיקות לפני בחירת חומרה או מוצר.','published','verified','2026-11-03',1,'מחקר 07/08 מאושר; דוגמאות ותרגילים מוצעים שלא הורצו. אין טענת SDK, רישוי או ביצועים מעבר למקורות.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved models07-20261103-v1 M07-01–M07-18 and inference08-20261103-v1 I08-01–I08-09 with overrides; docs/DECISIONS.md D-037');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('litellm','litellm','LiteLLM — AI Gateway ו־SDK','platform','שכבת gateway ו־Python SDK לניתוב בקשות למודלים ולשרתים, עם בקרה על מפתחות, תקציבים ו־fallback. אינה מנוע הסקה שמריץ משקלים; יש לבדוק מסלול נתונים, תכונות edition ורישוי.','published','verified','2026-11-03',1,'מחקר 07/08 מאושר; דוגמאות ותרגילים מוצעים שלא הורצו. אין טענת SDK, רישוי או ביצועים מעבר למקורות.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved models07-20261103-v1 M07-01–M07-18 and inference08-20261103-v1 I08-01–I08-09 with overrides; docs/DECISIONS.md D-037');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('onnxruntime-genai','onnxruntime-genai','ONNX Runtime GenAI','sdk','שכבת Generate API להרצת מודלים גנרטיביים בתוך היישום, עם API רשמי ל־C#. ממשק C# הוא Preview ועשוי להשתנות; יש להתאים מודל, חבילה ו־execution provider לפני בחירה.','published','verified','2026-11-03',1,'מחקר 07/08 מאושר; דוגמאות ותרגילים מוצעים שלא הורצו. אין טענת SDK, רישוי או ביצועים מעבר למקורות.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved models07-20261103-v1 M07-01–M07-18 and inference08-20261103-v1 I08-01–I08-09 with overrides; docs/DECISIONS.md D-037');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('sglang','sglang','SGLang','runtime','מנוע ומסגרת serving למודלים, להיכרות עם הגשת בקשות, caching ו־batching. משווים אותו ל־vLLM לפי מודל וחומרה מוגדרים, בלי להסיק ניצחון ביצועים גורף או תאימות לכל פלטפורמה.','published','verified','2026-11-03',1,'מחקר 07/08 מאושר; דוגמאות ותרגילים מוצעים שלא הורצו. אין טענת SDK, רישוי או ביצועים מעבר למקורות.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved models07-20261103-v1 M07-01–M07-18 and inference08-20261103-v1 I08-01–I08-09 with overrides; docs/DECISIONS.md D-037');
insert into academy.entry_categories (entry_id,category_id,position) values ('gemma','07',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('gemma','HTTP/JSON, יסודות LLM; לפריסה יש לקרוא גם יסודות inference ורישיון checkpoint.','דוגמה מעשית מוצעת שלא הורצה: ASP.NET Core מקבל פתק בקשת ציוד ומעביר אותו לשרת מקומי עם checkpoint של Gemma התואם לחומרה. המודל מחלץ itemId ו־quantity; Validator בודק אותם מול נתוני SQL לפני הצגת הצעה. משווים לאותה משימה עם Qwen באותו runtime ובאותם תנאי מדידה.','בחרו דגם, קראו את כרטיס המודל ואת הרישיון, ורשמו פורמט, כימות ומגבלות הקשר. הגדירו עשר בדיקות לחילוץ נתונים והשוו איכות, זיכרון וזמן בלי לטעון שדגם אחד טוב בכל משימה.','למשפחת משקלים אין SDK C# בפני עצמה. השילוב ב־.NET, Python או TypeScript נקבע לפי runtime, שרת HTTP או binding תואם. אין להסיק מתמיכה בשרת מסוים שכל דגם ופורמט נתמכים.','Qwen ו־Llama הן חלופות למשקלים זמינים; Phi למשימות עם דגם קטן; Gemini API לשירות מנוהל. הבחירה תלויה בחומרה, ברישיון ובבדיקות המשימה, לא בשם Google בלבד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('gemma',0,'מהי המשפחה ומה אינו כלול?','Gemma היא משפחת משקלים, בעוד Gemini API הוא שירות. בחירת משפחה אינה בחירת checkpoint, וגודל קטן או multimodal הם מאפייני דגם מסוים. לפני הורדה יש לקרוא תצורת קלט, הקשר ודרישות הרצה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('gemma',1,'הרצה והחיבור למערכת','בחרו runtime שתומך בדגם ובפורמט המשקלים. React פונה לשרת .NET, והשרת מפעיל מנוע מקומי או שירות נפרד. הקריאה למודל אינה הרשאה לעדכן SQL או לשלוח מידע לצד שלישי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('gemma',2,'רישוי לפי דגם','Gemma4 מופנית ברישיון Apache2 נפרד, בעוד התנאים המותאמים בעמוד Gemma חלים על הדגמים המנויים שם. אין לכתוב שכל המשפחה Apache2 או שכל המשפחה תחת תנאים מותאמים. רישיון runtime אינו רישיון המשקלים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('gemma',3,'יתרונות, חסרונות ומתי לבחור','יתרון לימודי: בדיקת מודל שאפשר להריץ בסביבה נבחרת מול שירות API. חסרונות: תאימות פורמט, זיכרון, תפעול ורישיונות משתנים. אין כאן בדיקת עברית או הבטחת איכות וזמן תגובה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('gemma',4,'השוואה לחלופות','השוו Gemma ל־Qwen או Phi על אותה משימה ומנוע; השוו לשירות Gemini כאשר תפעול מקומי אינו מטרה. יום ההשקה הראשון של המשפחה לא אומת במחקר ולכן אינו מתמלא מתאריך השקת דור מאוחר.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('gemma','should_know','כדאי להכיר כדי להבחין בין Gemini כשירות לבין מודל שניתן להריץ, ולתרגל בחירת משקלים ורישוי בלי ללמוד כל משפחה לעומק.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('gemma','משפחת מודלים במשקלים זמינים להשוואת הרצה, גודל ורישוי לפי הדגם שנבחר.','למשפחת משקלים אין SDK C# בפני עצמה. השילוב ב־.NET, Python או TypeScript נקבע לפי runtime, שרת HTTP או binding תואם. אין להסיק מתמיכה בשרת מסוים שכל דגם ופורמט נתמכים.','not_applicable','אין מאגר מוצר יחיד מייצג; אין שיוך Stars של SDK למשפחת מודלים.','2026-11-03');
