insert into academy.entry_categories (entry_id,category_id,position) values ('microsoft-phi','07',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('microsoft-phi','HTTP/JSON, יסודות LLM; לפריסה יש לקרוא גם יסודות inference ורישיון checkpoint.','דוגמה מעשית מוצעת שלא הורצה: יישום .NET מסווג פנייה לדוגמה לקטגוריית שירות באמצעות Phi נתמך, מאמת JSON ומציג needsReview כשהתוצאה אינה עוברת בדיקות. הפניה למודל ענן, אם נדרשת, מותרת רק לפי מדיניות מידע והרשאת המשתמש.','הגדירו dataset קטן של פניות, schema ושלושה מקרי כשל. השוו מודל קטן למודל גדול יותר, תוך רישום package, מודל וחומרה. אל תחשבו שפלט תקין מבנית הוא הוכחת נכונות עסקית.','C# יכול לצרוך שרת HTTP או runtime תואם כגון ONNX Runtime GenAI עם API C# המסומן Preview. זו תכונת סביבת ההרצה, לא SDK של משפחת Phi. יש לבדוק התאמת דגם, package ו־execution provider.','Gemma ו־Qwen להשוואת דגמים ומשקלים; שירותי OpenAI/Claude/Gemini כשניהול runtime אינו יעד. ONNX Runtime GenAI הוא כלי הרצה משלים, לא חלופת מודל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-phi',0,'משפחה, דגם וסביבה','Phi היא משפחת מודלים; בחירת checkpoint מתארת גודל, משימה ופורמט. אין להסיק מהמותג Microsoft שדגם תואם לכל GPU או שצריכתו נעשית תמיד דרך Azure.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-phi',1,'החיבור ל־.NET','אפשר לצרוך שרת מודלים דרך HTTP, או לבחור מודל נתמך ב־ONNX Runtime GenAI להפעלה בתוך התהליך. ה־Generate API ב־C# עדיין Preview. בחרו מודל וחבילת runtime יחד ולא כל אחד בנפרד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-phi',2,'רישוי ונכונות','כרטיסי Phi-4 ו־Phi-4-mini-instruct שנבדקו מציינים MIT. זהו תיאור checkpoints שנבדקו, לא קביעה על כל גרסה עתידית. פלט שפה, סיווג ושדות מחייבים eval נפרד; איכות בעברית לא נבדקה כאן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-phi',3,'יתרונות, חסרונות ומתי לבחור','מודל קטן הוא בסיס שימושי לבחינת משימה מוגדרת ועלויות הרצה. הוא עדיין צורך זיכרון, דורש packaging ועלול להיכשל בהסקה מורכבת. אין הבטחת התאמה למחשב מסוים ללא מדידה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-phi',4,'השוואה לחלופות','למדו להחליט מתי די במודל קטן ומתי נדרש מודל אחר או שירות מנוהל. השוו לרשומות Gemma/Qwen בלי להפוך fallback לענן לברירת מחדל החושפת מידע. יום ההשקה הראשון לא אומת ולכן נשאר חסר.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('microsoft-phi','should_know','כדאי להכיר להשוואת מודל קטן למשימה עסקית וללימוד תכנון מקומי רלוונטי ל־.NET, ללא הנחה שמודל קטן מספיק לכל משימה.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('microsoft-phi','משפחת מודלים קטנים לבחינת התאמה למשימה, חומרה והרצה מקומית בלי להחליף SDK במודל.','C# יכול לצרוך שרת HTTP או runtime תואם כגון ONNX Runtime GenAI עם API C# המסומן Preview. זו תכונת סביבת ההרצה, לא SDK של משפחת Phi. יש לבדוק התאמת דגם, package ו־execution provider.','not_applicable','אין מאגר מוצר יחיד מייצג; אין שיוך Stars של SDK למשפחת מודלים.','2026-11-03');
