insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('cohere-command','HTTP/JSON, יסודות LLM; לפריסה יש לקרוא גם יסודות inference ורישיון checkpoint.','דוגמה מעשית מוצעת שלא הורצה: ASP.NET Core מאחזר קטעי נוהל מורשים ומבקש מ־Command תשובה עם מזהי מקורות. השרת בודק שכל מקור שייך למשתמש ומסמן תשובה חסרת ראיה לבדיקה. אותו אוסף שאלות משמש להשוואה מול Claude או OpenAI.','מפו את שלבי האחזור, דירוג הקטעים ויצירת התשובה. הגדירו מתי Rerank נחוץ ומתי אינו משנה את תפקיד המודל. בדקו תנאי שימוש למסלול ההרצה לפני שימוש עסקי.','אפשר לצרוך API משירות C#/.NET דרך HTTP; SDK C# רשמי ייעודי לא אומת במחקר. פורמט וממשקי SDK נקבעים לפי מוצר וגרסה, ולא לפי עצם קיומו של REST.','OpenAI, Claude ו־Gemini הם חלופות generation להשוואה באותו eval. כלי embeddings ו־rerank משלימים מודל, ואינם בהכרח תחליף לו. RAGFlow ו־LlamaIndex הן שכבות מערכת שכבר קיימות בקטלוג.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cohere-command',0,'איזו שכבה לומדים?','Command הוא שם משפחת generation. Embed מייצר ייצוגים ו־Rerank מדרג מועמדים; אלה משימות ומוצרים אחרים של אותו ספק. הפרק אינו מסווג ספק שירות כמאגר וקטורי או כמסגרת RAG שלמה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cohere-command',1,'תכנון RAG במערכת עסקית','יישום מאחזר מידע מורשה ומעביר הקשר מוגבל למודל. השרת אחראי לאימות המקורות, לסירוב כשאין ראיה ולמניעת פעולות לא מורשות. הגישה ל־API אינה מחליפה תכנון הרשאות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cohere-command',2,'רישוי ודרכי גישה','כרטיס Command A שנבדק הוא תחת CC-BY-NC4. אין להסיק ממנו היתר מסחרי חופשי; תנאי שירות API ורישוי Enterprise נפרדים. יש לבחור מסלול מאושר במקום להניח שרישיון המשקלים זהה לתנאי הענן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cohere-command',3,'יתרונות, חסרונות ומתי לבחור','ערך לימודי: השוואת generation לצד כלים נפרדים לאחזור ודירוג. חסרונות: עוד חוזה API, עלויות ותנאי נתונים; אין בדוח benchmark המצדיק עדיפות איכות גורפת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cohere-command',4,'השוואה לחלופות','השוו תשובות ל־Claude/OpenAI על אותה שאלה ומקורות. שיפור retrieval עשוי לתרום יותר מהחלפת ספק, ולכן בדקו שני שלבים בנפרד. תאריך השקה ראשונה לא אומת ולא נגזר מפרסום checkpoint מסוים.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('cohere-command','should_know','כדאי להכיר כדי להשוות ספק generation מוכוון ידע ארגוני ולהבין את ההפרדה בין יצירה, embeddings ו־reranking.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('cohere-command','מודלי generation להשוואת פתרונות ידע ארגוניים, בנפרד משירותי embeddings ו־reranking של הספק.','אפשר לצרוך API משירות C#/.NET דרך HTTP; SDK C# רשמי ייעודי לא אומת במחקר. פורמט וממשקי SDK נקבעים לפי מוצר וגרסה, ולא לפי עצם קיומו של REST.','not_applicable','אין מאגר מוצר יחיד מייצג; אין שיוך Stars של SDK למשפחת מודלים.','2026-11-03');
