insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('inference-fundamentals','HTTP/JSON, יסודות LLM; לפריסה יש לקרוא גם יסודות inference ורישיון checkpoint.','דוגמה מעשית מוצעת שלא הורצה: React שולח פתק שירות ל־ASP.NET Core, שמבקש ממודל מקומי JSON עם מספר הזמנה ותאריך. מקבעים checkpoint, כימות, חומרה ואורך פלט; מודדים זמן טעינה, TTFT, קצב, p95 ושגיאות, ומאמתים איכות. מעבר לענן אינו מותר בלי מדיניות מפורשת.','שרטטו ארבע שכבות: משקלים, runtime, API שרת ו־gateway. הגדירו dataset קבוע ותנאי מדידה. הסבירו איך תבדקו שאין תעבורה לענן, בלי להסיק זאת רק מכתובת localhost.','העקרונות מתאימים ל־.NET, Python ו־TypeScript. מנוע C++ או Python אינו בהכרח SDK ללקוח; אפשר לצרוך HTTP או binding תואם לפי כלי. C# Generate API של ONNX GenAI הוא Preview.','Ollama או LM Studio להרצה ראשונה; llama.cpp להבנת מנוע וכימות; ONNX GenAI להפעלה בתוך .NET; vLLM או SGLang להגשת עומס; LiteLLM לניתוב בין endpoints ולא ליצירת tokens.');
insert into academy.entry_sections (entry_id,position,title,body) values ('inference-fundamentals',0,'מודל, מנוע ושרת','מודל הוא המשקלים והמבנה; runtime מבצע חישוב; שרת מנהל בקשות; gateway מנתב ומפעיל מדיניות. אותו מוצר עשוי לכלול יותר מתפקיד אחד, אבל אין להשוות מנוע לספק ענן כאילו הם אותה שכבה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('inference-fundamentals',1,'פורמט, כימות וזיכרון','פורמט המשקלים והכימות חייבים להתאים למנוע ולמודל. RAM ו־VRAM נצרכים גם למצב ול־KV cache, לא רק למשקלים. כימות משנה תנאי חישוב ואיכות; אין להבטיח מהירות או דיוק ללא מדידה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('inference-fundamentals',2,'Latency, batch ובקרה','זמן לתשובה יחידה שונה מקצב כולל. מדדו TTFT, זמן סיום, p95, שגיאות וזיכרון על אותו עומס. המלצת תכנון: תור מוגבל, timeout ו־backpressure בשרת היישום לפני העברה למנוע.');
insert into academy.entry_sections (entry_id,position,title,body) values ('inference-fundamentals',3,'נתיב נתונים והרשאות','localhost אינו הוכחת local-only: runtime או gateway יכולים לפנות לענן, לכלים ולשירותים חיצוניים. בדקו egress, הורדות, fallback וטלמטריה; חיבור מקומי פתוח אינו מנגנון הרשאת משתמש עסקי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('inference-fundamentals',4,'יתרונות, חסרונות ובחירה','הרצה עצמאית יכולה לתת שליטה בתצורה ובמיקום ההסקה, אך מוסיפה packaging, תחזוקה ואבטחה. התחילו בכלי אחד ובמשימה קטנה; אין חובה לקנות GPU או להפעיל cluster כדי ללמוד את גבולות המערכת.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('inference-fundamentals','must_learn','חובה להבין משקלים, זיכרון, API ונתיב נתונים לפני שמוסיפים GPU או מחליפים שרת בגלל מספר ביצועים יחיד.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('inference-fundamentals','יסודות הרצת מודלים, זיכרון וכימות, הגשת בקשות, נתיב מידע ומדידת איכות ועלות.','העקרונות מתאימים ל־.NET, Python ו־TypeScript. מנוע C++ או Python אינו בהכרח SDK ללקוח; אפשר לצרוך HTTP או binding תואם לפי כלי. C# Generate API של ONNX GenAI הוא Preview.','not_applicable','אין מאגר מוצר יחיד מייצג; אין שיוך Stars של SDK למשפחת מודלים.','2026-11-03');
