insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('litellm','HTTP/JSON, יסודות LLM; לפריסה יש לקרוא גם יסודות inference ורישיון checkpoint.','דוגמה מעשית מוצעת שלא הורצה: שרת ASP.NET משתמש במפתח מוגבל ל־gateway, המנתב ל־Ollama מקומי או לספק שאושר. תקציב, ספקי fallback ונתוני לוג נקבעים לפי מדיניות. כשל מקומי אינו היתר לשלוח מידע חסוי לענן.','ציירו adapter יחיד מול gateway והגדירו allowlist ספקים, timeout ותקציב. בדקו איזה edition נדרש לכל תכונה; הגדירו מבחן שמונע fallback לספק שלא אושר.','מוצרי Python SDK ושרת proxy נפרדים. C#/.NET ו־TypeScript יכולים לצרוך HTTP; זה אינו SDK LiteLLM רשמי ל־C#. תאימות OpenAI אינה הוכחת כיסוי לכל endpoint או מודל.','OpenRouter הוא שירות ניתוב מנוהל ולא אותו מודל תפעול; adapter ישיר ב־.NET מפחית שכבת תיווך לספק יחיד. vLLM/SGLang מריצים את המודל ויכולים לשבת מאחורי LiteLLM.');
insert into academy.entry_sections (entry_id,position,title,body) values ('litellm',0,'מה היא פותרת?','LiteLLM מוסיפה גבול משותף לפני ספקים ומנועים. Gateway מקבל בקשה ומנתב אותה לפי מדיניות; הוא אינו טוען לבדו את משקלי המודל כמו engine. מיקום ב־08 מתאר תשתית serving ולא משפחת LLM.');
insert into academy.entry_sections (entry_id,position,title,body) values ('litellm',1,'ממשקים וזרימת בקשה','Python SDK הוא ספרייה ו־proxy הוא שרת עצמאי. .NET יכול לפנות ל־HTTP ולשמור את הלוגיקה העסקית ביישום. יש לבדוק תכונות נדרשות אצל הספק בפועל ולא רק שהבקשה נראית תואמת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('litellm',2,'יתרונות ומתי לבחור','ריבוי endpoints וצוותים עשוי להצדיק מפתחות ותקציבים במקום אחד. ניתוב ואפשרויות fallback מאפשרים תכנון זמינות, אך מדיניות נתונים צריכה להגביל את הנתיבים המותרים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('litellm',3,'חסרונות ורישוי','השרת מוסיף hop, ניטור ותפעול; לוגים ומאגר בקרה דורשים הרשאות ושמירה מתוכננת. הקוד מחוץ ל־enterprise הוא MIT, ויכולות Enterprise כפופות לרישיון נפרד. אין הבטחה שכל יכולת זמינה במסלול החופשי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('litellm',4,'השוואה לחלופות','לספק יחיד התחילו ב־adapter בדוק; לריבוי שירותים השוו ניהול gateway מקומי לשירות ניתוב מנוהל. אין כאן הבטחת חיסכון או ביצועים. יום השקה ראשון לא אומת ולכן נשאר חסר.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('litellm','should_know','כדאי להכיר כשנדרש גבול תשתיתי לריבוי ספקים וצוותים; ליישום עם ספק יחיד עשוי להספיק adapter קטן בקוד.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('litellm','מרכזת ניתוב, מפתחות ותקציבי API בין יישומים לספקי מודלים ולמנועי הסקה.','מוצרי Python SDK ושרת proxy נפרדים. C#/.NET ו־TypeScript יכולים לצרוך HTTP; זה אינו SDK LiteLLM רשמי ל־C#. תאימות OpenAI אינה הוכחת כיסוי לכל endpoint או מודל.','verified','מאגר ליבת הפרויקט; מדידת מחקר מתוארכת, ללא שינוי מדגמי Interest.','2026-11-03');
