insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('onnxruntime-genai','HTTP/JSON, יסודות LLM; לפריסה יש לקרוא גם יסודות inference ורישיון checkpoint.','דוגמה מעשית מוצעת שלא הורצה: אפליקציית .NET טוענת מודל ONNX נתמך ומחלצת שדות מפתק שירות לדוגמה בלי שרת HTTP הכרחי. מאמתים DTO ומודדים זיכרון וזמן על המחשב הנבחר; אין הסקה שפעולת הרצה כזו מבטיחה offline לכל היישום.','בדקו את ה־package ואת המודל הנתמכים יחד. הגדירו בדיקות טוקניזציה, עצירת generation, פלט לא תקין ומגבלת זיכרון. השוו לתהליך נפרד עם Ollama; תעדו סיכון שינוי API של Preview.','API רשמי ל־C#/.NET, לצד Python ו־C/C++. ממשק C# הוא Preview ולא GA. תאימות תלויה ב־package, מודל ו־execution provider; אין הבטחה לכל checkpoint או חומרה ואין שוויון גורף בין השפות.','Ollama ו־LM Studio לשרת נפרד; llama.cpp למנוע בפורמטים מתאימים; vLLM/SGLang להגשת עומס. ONNX Runtime הרגיל אינו זהה לשכבת GenAI ו־Phi הוא מודל, לא runtime.');
insert into academy.entry_sections (entry_id,position,title,body) values ('onnxruntime-genai',0,'מהי שכבת GenAI?','הספרייה עוזרת לנהל יצירת טוקנים ומצב generation מעל ONNX Runtime. היא אינה ספק מודלים ואינה רק עטיפת HTTP; אפשר להפעיל מודל בתוך התהליך. התאמת tokenizer ומבנה המודל היא חלק מהבחירה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('onnxruntime-genai',1,'C# Preview במפורש','ממשק Generate API ל־C# הוא Preview ועשוי להשתנות. אל תציגו אותו כ־GA רק מפני שקיים package או release tag. לפני production יש לקבע גרסה ולבדוק תאימות ותוכנית שדרוג.');
insert into academy.entry_sections (entry_id,position,title,body) values ('onnxruntime-genai',2,'מודל, package וחומרה','בחרו execution provider וחבילת runtime התואמים לפלטפורמה, ולצידם מודל בפורמט נתמך. ONNX אינו הבטחה שכל מודל ניתן להמרה אוטומטית או שכל מאיץ זמין באותו package.');
insert into academy.entry_sections (entry_id,position,title,body) values ('onnxruntime-genai',3,'יתרונות, חסרונות ומתי לבחור','הפעלה בתוך .NET מאפשרת ללמוד גבול תהליך וזיכרון בלי שרת API הכרחי. חסרונות: packaging, תלויות native, תאימות ו־Preview. רישיון MIT של הקוד נפרד מרישיון המשקלים; אין benchmark של איכות או מהירות כאן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('onnxruntime-genai',4,'השוואה לחלופות','שרת נפרד מפריד תפעול וסביבת ריצה; in-process דורש ניהול משאבים בתוך היישום. השוו שתי חלופות על משימה קטנה לפני בחירת מוצר. יום ההשקה הראשון לא אומת ונשאר חסר.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('onnxruntime-genai','should_know','כדאי להכיר למפתח .NET כדי להבין הסקה בתוך תהליך כחלופה לשרת HTTP, תוך התחשבות ב־Preview ובתאימות.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('onnxruntime-genai','מספקת Generate API להרצה בתוך היישום עם C# רשמי במצב Preview והתאמה למודל ולחומרה.','API רשמי ל־C#/.NET, לצד Python ו־C/C++. ממשק C# הוא Preview ולא GA. תאימות תלויה ב־package, מודל ו־execution provider; אין הבטחה לכל checkpoint או חומרה ואין שוויון גורף בין השפות.','verified','מאגר ליבת הפרויקט; מדידת מחקר מתוארכת, ללא שינוי מדגמי Interest.','2026-11-03');
