insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('sglang','HTTP/JSON, יסודות LLM; לפריסה יש לקרוא גם יסודות inference ורישיון checkpoint.','דוגמה מעשית מוצעת שלא הורצה: ASP.NET Core מווסת עומס של בקשות חילוץ נתונים ומעביר אותן לשרת SGLang. אותה משימה, חומרה, מודל וכימות משמשים להשוואה מול vLLM, תוך מדידת זמן תגובה, תור, שגיאות וזיכרון.','תכננו ניסוי A/B בין שני מנועים בלי לשנות מודל או workload. רשמו מטריצת חומרה נתמכת, תקרת concurrency ותוכנית rollback. אל תסיקו כיסוי Windows מתמיכת Linux או CUDA.','מסלולי Python ושרת HTTP מאפשרים שילוב מ־.NET בלי להעביר לוגיקה עסקית למנוע. SDK C# מקומי רשמי לא אומת. התקנה ותכונות תלויות backend, חומרה, מודל וגרסה.','vLLM הוא חלופה באותו תפקיד serving; Ollama ו־LM Studio להתחלה נוחה יותר; llama.cpp ללימוד מנוע וכימות. LiteLLM הוא gateway משלים ולא חלופת engine.');
insert into academy.entry_sections (entry_id,position,title,body) values ('sglang',0,'איזה תפקיד הוא ממלא?','SGLang מריץ ומגיש מודלים; הוא אינו המשקלים עצמם ואינו נתב ספקים בלבד. לומדים אותו אחרי בקשת inference אחת כדי להבין משאבים, תורים ומדיניות הגשה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('sglang',1,'ממשקים וסביבת ריצה','שרת .NET יכול לצרוך HTTP; קוד Python שייך לשכבת המנוע ולא מוכיח SDK .NET מקומי. יש לבדוק את המודל וה־backend הנתמכים במדריך ההתקנה שנבחר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('sglang',2,'יתרונות ומתי לבחור','הכלי מוסיף חלופה משמעותית לדיון ב־serving, caching ו־batching. הערך הוא ללמוד לזהות צוואר בקבוק ולבדוק מנוע באותו תרחיש, לא לקבל דירוג מהירות אוניברסלי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('sglang',3,'חסרונות, חומרה ורישוי','סביבת GPU ותלויות עשויות להיות מורכבות; תיעוד התחלה המתמקד Linux/NVIDIA אינו הבטחה לשוויון בכל backend או ב־Windows. Apache2 של הקוד אינו רישיון המשקלים, ופעילות מאגר אינה אישור אבטחה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('sglang',4,'השוואה לחלופות','בחרו בין vLLM ל־SGLang על בסיס ניסוי תואם ויכולות נדרשות. אם מטרת הלמידה היא רק קריאה מקומית אחת, Ollama או LM Studio עשויים להספיק. יום ההשקה הראשון לא אומת; אין סיווג Legacy או יציבות רק לפי מספר גרסה.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('sglang','should_know','כדאי להכיר אחרי vLLM כדי להשוות תכנון serving וקיבולת, לא כדי להתקין עוד מנוע בלי צורך.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('sglang','מגיש מודלים ובקשות מקבילות עם מנגנוני caching ו־batching, כחלופה להשוואה ל־vLLM.','מסלולי Python ושרת HTTP מאפשרים שילוב מ־.NET בלי להעביר לוגיקה עסקית למנוע. SDK C# מקומי רשמי לא אומת. התקנה ותכונות תלויות backend, חומרה, מודל וגרסה.','verified','מאגר ליבת הפרויקט; מדידת מחקר מתוארכת, ללא שינוי מדגמי Interest.','2026-11-03');
