insert into academy.entry_sections (entry_id,position,title,body) values ('llm-fundamentals',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','משפחה, checkpoint, ספק ו־endpoint הם שכבות שונות. מכסת context כוללת קלט ופלט ולעיתים tokens להסקה; פלט JSON תקין אינו הרשאה לבצע פעולה.');
