insert into academy.entry_sections (entry_id,position,title,body) values ('llm-fundamentals',7,'חסרונות והשוואה לחלופות','הבנת מושגים לבדה אינה מוכיחה התאמה למשימה; יש לתרגל על נתונים מייצגים. אין בפרק תוצאת benchmark או ניסוי מוצר שבוצע בפרויקט.');
