insert into academy.entry_sections (entry_id,position,title,body) values ('openai-gpt',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','OpenAI מספקת client .NET רשמי. Responses הוא ממשק API, לא שם משפחת מודלים; יש להצמיד model ID ולבדוק תמיכת כלים, פלט מובנה ו־streaming לפי המודל והממשק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('openai-gpt',6,'יתרונות ומתי לבחור','SDK .NET רשמי מצמצם קוד חיבור; Responses מאפשר ללמוד מסלול API עדכני בחוזה מוגדר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('openai-gpt',7,'חסרונות והשוואה לחלופות','תלות בשירות מנוהל, עלות ותנאי מידע; ניידות ל־Claude או Gemini דורשת בדיקות חוזה ולא החלפת model ID בלבד. אין בפרק תוצאת benchmark או ניסוי מוצר שבוצע בפרויקט.');
