insert into academy.entry_sections (entry_id,position,title,body) values ('meta-llama',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','Llama היא משפחת משקלים ולא SDK. Llama 4 Scout מופצת ברישיון Llama 4 מותאם; אין לתארה כ־Apache או MIT ואין להכליל תנאי checkpoint אחד לכל המשפחה. הבנת משקלים ורישוי נשארת חובה ללמוד.');
