insert into academy.entry_sections (entry_id,position,title,body) values ('qwen',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','Qwen היא משפחה רחבה: Qwen3-8B הוא דוגמת checkpoint ברישיון Apache 2.0, ולא ראיה לרישיון אחיד לכל Qwen או שירות מסחרי. הבנת בחירת checkpoint ורישוי נשארת חובה ללמוד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('qwen',6,'יתרונות ומתי לבחור','משפחה עם גדלים ומשימות שונים מתאימה לתרגול בחירה וריצה במנועים מגוונים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('qwen',7,'חסרונות והשוואה לחלופות','שם משפחה אינו מבטיח רישיון אחיד או יכולת זהה; השוו ל־Llama או Phi לפי checkpoint ונתוני המשימה. אין בפרק תוצאת benchmark או ניסוי מוצר שבוצע בפרויקט.');
