insert into academy.entry_sections (entry_id,position,title,body) values ('mistral-ai',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','רשימת SDK הרשמית מבחינה בלקוחות Python/TypeScript לעומת third-party. לא אומת SDK C# רשמי ייעודי. רישיון API מסחרי נפרד מרישיונות checkpoints זמינים.');
