insert into academy.entry_sections (entry_id,position,title,body) values ('hugging-face',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','Hugging Face Hub וקריאת Model Cards הם בסיס חשוב מאוד ללמידה: רישיון, מגבלות, אופן אימון ושימוש. Inference Providers הוא שירות גישה נפרד, ו־Endpoints מסלול פריסה אחר; המדיניות תלויה גם בספק בפועל.');
