insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-foundry',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','בחרו SDK לפי endpoint: לקוח פרויקט Foundry לניהול משאבי פרויקט; לקוח OpenAI עבור מסלול OpenAI v1; לקוח Anthropic עבור מסלולו. אין לקוח יחיד שמבטיח כל יכולת. לא פורסם תאריך פרישה ל־SDK כי לא אומת מחדש. Foundry עצמה אינה מסומנת Legacy.');
