insert into academy.entry_sections (entry_id,position,title,body) values ('google-vertex-ai',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','Gemini Enterprise Agent Platform מוצגת לצד השם המוכר Vertex AI; זהו מסלול ענן עם מודלים מנוהלים ופריסה לפי מוצר, לא משפחת משקלים חדשה ולא הבטחת פריסה עצמית לכל מודל. ה־slug נשמר.');
