insert into academy.entry_sections (entry_id,position,title,body) values ('google-vertex-ai',7,'חסרונות והשוואה לחלופות','שינוי שם אינו מייתר בדיקת שירות, region ו־endpoint; Gemini API ישיר עשוי להספיק לניסוי בסיסי. אין בפרק תוצאת benchmark או ניסוי מוצר שבוצע בפרויקט.');
