insert into academy.entry_sections (entry_id,position,title,body) values ('amazon-bedrock',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','AWS SDK for .NET v4 כולל דוגמאות Bedrock Runtime ו־Converse. IAM, region ומטריצת יכולות המודל קובעים גישה; Converse אינו מבטיח שכל מודל תומך באותם כלים או פורמטים.');
