insert into academy.entry_sections (entry_id,position,title,body) values ('ollama',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','Ollama מפשטת הורדה והרצה, ומציעה גם מסלולי cloud: אין להציג כל שימוש כאוטומטית מקומי. API מקומי אינו דורש אימות כברירת מחדל; אין לחשוף port לרשת בלתי מהימנה. קוד runtime ומשקלים כפופים לרישיונות נפרדים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ollama',6,'יתרונות ומתי לבחור','נוחה לבקשה ראשונה ולחיבור HTTP ממערכת .NET.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ollama',7,'חסרונות והשוואה לחלופות','נוחות אינה שליטה מלאה בשרת או הבטחת local-only; llama.cpp מאפשר לימוד מנוע מפורט יותר, ו־LM Studio מציעה גם ממשק חזותי. אין בפרק תוצאת benchmark או ניסוי מוצר שבוצע בפרויקט.');
