insert into academy.entry_sections (entry_id,position,title,body) values ('llama-cpp',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','llama.cpp הוא מנוע עם שרת ולא משפחת Llama. GGUF וכימות משנים זיכרון ואיכות; batching ופלט מובנה דורשים בדיקה לפי השרת והמודל. schema תקין אינו בדיקת אמת או הרשאה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('llama-cpp',6,'יתרונות ומתי לבחור','GGUF וכימות חושפים את הקשר בין מודל, זיכרון והרצה על חומרות נתמכות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('llama-cpp',7,'חסרונות והשוואה לחלופות','דורשת יותר הבנת מנוע מתוכנת התחלה; vLLM או SGLang מכוונים ל־serving אחר ואינם הבטחה לביצועים טובים יותר בכל חומרה. אין בפרק תוצאת benchmark או ניסוי מוצר שבוצע בפרויקט.');
