insert into academy.entry_sections (entry_id,position,title,body) values ('vllm',5,'תיקון מאומת ומסלול שילוב — 2026-11-03','vLLM הוא מנוע serving. יש להצמיד תמיכת חומרה, backend ותלויות לגרסה שנבדקת. api-key אינו מגן בהכרח על כל נתיבי השרת; נדרשים גבול רשת ומדיניות endpoint. תג v0.33.0rc3 סותר תיאור release מסוים ולכן אין כאן טענה לגרסה יציבה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('vllm',6,'יתרונות ומתי לבחור','מאפשרת ללמוד concurrency, batching וקיבולת בשרת הסקה עצמאי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('vllm',7,'חסרונות והשוואה לחלופות','תלות בחומרה ובגרסה ואחריות אבטחה ותפעול; השוו ל־SGLang באותו workload. LiteLLM הוא gateway משלים ולא מנוע מתחרה. אין בפרק תוצאת benchmark או ניסוי מוצר שבוצע בפרויקט.');
