insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('07',0,'llm-fundamentals','הבחינו משפחה/checkpoint/provider/endpoint, tokens והרשאות; הגדירו eval לפני בחירת מודל.','יסודות LLM');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('07',1,'openai-gpt','תרגלו SDK רשמי או HTTP, פלט מובנה, שגיאות ו־timeout בספק אחד. השוו Claude או Gemini באותן בדיקות, בלי ללמוד כל ספק באותו עומק.','מסלול API ראשון');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('07',2,'meta-llama','קראו Model Card ורישיון checkpoint; השוו ל־Qwen ול־Gemma או Phi. עברו ליסודות inference ב־08 כדי להפריד מודל ממנוע.','משקלים ורישוי');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('07',3,'hugging-face','השתמשו ב־Hub וב־Model Cards להחלטות; הפרידו Providers מ־Endpoints ומרישיון המשקלים.','קריאת כרטיסי מודל');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('07',4,'openrouter','בחנו נתב רק כאשר נדרשים ספקים מרובים: תעדו ספק בפועל, fallback, פרטיות ועלות; LiteLLM ב־08 הוא מסלול gateway בשליטתכם.','ניתוב מבוקר');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('07',5,'microsoft-foundry','בחרו ענן ארגוני לפי סביבת הארגון: Foundry, Google Platform או Bedrock. אמתו SDK/endpoint/IAM/region ויכולות, בלי להוסיף שלושה עננים לאותה מעבדה.','מסלול ארגוני');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('08',0,'inference-fundamentals','הבינו זיכרון, quantization, KV cache, latency לעומת throughput, הרשאות וגבול רשת לפני התקנה.','יסודות inference');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('08',1,'ollama','התחילו בבקשה מקומית אחת דרך HTTP; LM Studio היא חלופה עם GUI וגם llmster headless. בדקו בפועל מקומי/ענן ואימות.','הרצה ראשונה');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('08',2,'llama-cpp','השוו GGUF וכימות באותו checkpoint ובאותו eval; בדקו batching, structured output וזיכרון.','המנוע והמשקלים');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('08',3,'onnxruntime-genai','לתרחיש embedded ב־.NET בדקו המרת מודל, execution provider ו־C# Preview; Phi היא מועמדת לבחינה ולא הבטחת תאימות.','מסלול C# מקומי');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('08',4,'vllm','ל־GPU serving השוו vLLM ו־SGLang באותו workload, עם תקרות עומס, חומרה נתמכת ואבטחת כל הנתיבים.','Serving מתקדם');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('08',5,'litellm','הוסיפו gateway כשנדרשים routing, quotas ותצפית; הוא אינו מנוע GPU ואינו מבטל מדיניות ספקים.','שכבת gateway');
insert into academy.schema_migrations(version,description) values(12,'Approved models07/inference08 research: seven additions, eighteen corrections, two learning guides and user overrides');
