 if (select document from academy.entry_documents where slug='amazon-bedrock') is distinct from '{"id":"amazon-bedrock","kind":"platform","name":"Amazon Bedrock","slug":"amazon-bedrock","addedAt":"2026-10-31","example":"תכנון לימודי: שירות בקשות ציוד בארגון המשתמש ב־AWS ניגש למודל דרך Bedrock ומחזיר DTO מאומת לשירות העסקי.","sources":[{"url":"https://docs.aws.amazon.com/bedrock/latest/userguide/what-is-bedrock.html","title":"AWS — Amazon Bedrock Overview","supports":"שירות מודלי בסיס מנוהל וריבוי ממשקי גישה. ניתוח האחריות הוא שלנו.","checkedAt":"2026-10-31"}],"summary":"שירות AWS מנוהל ללימוד גישה למשפחות מודלים שונות והפרדה בין מודל, הרשאות וממשק ענן.","exercise":"צייר מסלול גישה ישיר לספק מול Bedrock. תוצר: רשימת החלטות על זהות, אזור, ממשק ותיעוד בקשות; ללא יצירת משאבים.","revision":2,"sections":[{"text":"Amazon Bedrock הוא שירות מנוהל לגישה למודלי בסיס ממספר ספקים. בחירה ב־Bedrock היא בחירת דרך גישה ותפעול, ולא שם של משפחת LLM אחת.","title":"מהו השירות?"},{"text":"התיעוד מציג מספר ממשקים, ובהם Converse ו־Invoke וכן ממשקים תואמים. לפני מימוש יש לבחור חוזה נתמך לדגם הרצוי, ולא להניח שכל דגם עובד בכל מסלול.","title":"חוזי גישה"},{"text":"תכנון לימודי: Adapter בשירות C# מתרגם בקשה עסקית לממשק הענן. ההזדהות וההרשאות מתוכננות בצד השרת; React אינו מחזיק סוד גישה לשירות.","title":"החיבור ל־REST ול־.NET"},{"text":"אחרי שהבנת קריאת מודל ישירה, למד את השפעת אזור, הרשאות וקיבולת על בחירה. אין צורך ללמוד שלושה עננים באותה רמת עומק; המטרה היא להבין את השכבות המשותפות.","title":"מתי להעמיק?"},{"text":"בדוק זמינות, תנאי עיבוד, מגבלות וכלים לדגם ולממשק המדויקים. שם מודל זהה אצל כמה מארחים אינו מבטיח חוזה או מדיניות זהים.","title":"בדיקת התאמה"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["microsoft-foundry","google-vertex-ai","anthropic-claude"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"השווה מול Foundry ופלטפורמת Google Cloud ברמת אחריות וחוזים, בלי להניח יתרון עלות או איכות גורף.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"אפשר לתכנן לקוח C# באמצעות HttpClient מול HTTP API. זו דרך אינטגרציה, לא טענה שקיים SDK רשמי לכל שפה. חבילות, גרסאות וכיסוי יכולות נבדקים בנפרד לפני מימוש."}'::jsonb then raise exception 'Reviewed document changed: amazon-bedrock'; end if;
 if (select document from academy.entry_documents where slug='anthropic-claude') is distinct from '{"id":"anthropic-claude","kind":"model","name":"Anthropic — Claude","slug":"anthropic-claude","addedAt":"2026-10-31","example":"תכנון לימודי: Claude מבקש get_stock; שרת .NET מאמת itemId, קורא SQL ומחזיר תוצאה. המודל מנסח הסבר על זמינות.","sources":[{"url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/overview","title":"Anthropic — Tool use with Claude","supports":"כלי לקוח ושרת, tool_use ו־tool_result. ההמלצות העסקיות הן שלנו.","checkedAt":"2026-10-31"}],"summary":"משפחת מודלים ללימוד לולאת כלים והבדלה בין כלים שהיישום מפעיל לכלים שמופעלים אצל הספק.","exercise":"צייר רצף הודעות הכולל tool_use, כשל עסקי ו־tool_result. תוצר: תרשים רצף והחלטה מה קורה אם המודל מבקש כלי שאינו מורשה.","revision":2,"sections":[{"text":"Anthropic מפתחת את Claude. Claude Code הוא מוצר לפיתוח תוכנה ואינו שם חלופי ל־API של המודל. כדאי ללמוד מודל נוסף כדי להבין אילו חלקים באפליקציה תלויים בספק.","title":"ספק, מודל ומוצר"},{"text":"בכלי לקוח המודל מחזיר tool_use, היישום מבצע את הפונקציה ומחזיר tool_result. בכלי שרת הביצוע מתרחש אצל הספק. ההבחנה קובעת היכן נדרשות הרשאות, ניטור וטיפול בכשל.","title":"איך לולאת הכלים עובדת?"},{"text":"הקבלה לימודית: בקשת כלי היא בקשה להפעלת Endpoint פנימי, לא קריאת REST שכבר התבצעה. מתאם בשרת ממפה שם כלי לפונקציה מאושרת ובודק את הפרמטרים והמשתמש.","title":"החיבור ל־REST"},{"text":"השווה מול ספק נוסף את בחירת הכלי, איכות הארגומנטים והתגובה לשגיאת מלאי. אין כאן קביעה ש־Claude טוב יותר לקוד או להסקה; זו שאלה לניסוי מוגדר.","title":"מה כדאי להשוות?"},{"text":"תכנן עצירה אחרי מספר צעדים מוגבל והפרד כלי קריאה מכלי כתיבה. תוכן שחוזר ממסמך או מכלי הוא מידע לא מהימן, ולא מקור להרשאות חדשות.","title":"גבולות ואבטחה"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["openai-gpt","google-gemini","claude-code"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"OpenAI ו־Gemini הם חלופות ללימוד אותו תרחיש. אל תעתיק מבנה הודעות מספק אחד לאחר בלי לבדוק את החוזה.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"אפשר לתכנן לקוח C# באמצעות HttpClient מול HTTP API. זו דרך אינטגרציה, לא טענה שקיים SDK רשמי לכל שפה. חבילות, גרסאות וכיסוי יכולות נבדקים בנפרד לפני מימוש."}'::jsonb then raise exception 'Reviewed document changed: anthropic-claude'; end if;
 if (select document from academy.entry_documents where slug='deepseek') is distinct from '{"id":"deepseek","kind":"model","name":"DeepSeek","slug":"deepseek","addedAt":"2026-10-31","example":"תכנון לימודי: מנתח בקשות ציוד מחליף ספק מאחורי אותו ממשק, ומבחני חוזה מגלים אם טיפול בפלט חלקי נשבר.","sources":[{"url":"https://api-docs.deepseek.com/","title":"DeepSeek — First API Call","supports":"כתובות API, פורמטים תואמים ותצורת בקשות. בדיקות הניידות הן תכנון שלנו.","checkedAt":"2026-10-31"}],"summary":"ספק ומשפחות מודלים ללימוד מעבר בין שירותים והגבולות של תאימות לממשקי API מוכרים.","exercise":"כתוב רשימת בדיקות למעבר ספק: הזדהות, פלט, שגיאות, timeout וכלים. תוצר: תוכנית בדיקה המפרידה בין תאימות פורמט לתאימות התנהגות.","revision":2,"sections":[{"text":"DeepSeek מוסיף למסלול הלימוד ספק מודלים נוסף. המוקד כאן הוא ההבחנה בין ספק, מזהה מודל ודרך גישה, ולא הנחה שהוא זול או איכותי יותר מספקים אחרים.","title":"למה להכיר?"},{"text":"התיעוד מציג גישה בפורמטים תואמי OpenAI ו־Anthropic באמצעות הגדרת כתובת ומודל. תאימות פורמט אינה הוכחה לשוויון ביכולות, שגיאות, מדיניות מידע או פרמטרים.","title":"תאימות API"},{"text":"תכנון לימודי: שמור כתובת, מזהה מודל והגדרות בספק תצורה. מתאם מפרש תשובות ושגיאות לפורמט פנימי. החלפת כתובת דורשת בדיקות חוזה, ולא רק קומפילציה.","title":"איך מחליפים ספק?"},{"text":"מצבי הסקה ופרטי בקשה משתנים לפי הדגם. בדוק מה היישום מקבל בפועל וכיצד הוא מתמודד עם פלט חסר. אורך הסבר אינו מדד מספיק לנכונות הפתרון.","title":"הקשר להסקה ול־Agents"},{"text":"בחן אזור עיבוד, תנאי שימוש, מגבלות ותיעוד שגיאות לפני שילוב. פרק זה אינו סקירת רישיונות משקלים או המלצה לפריסת דגם מקומי מסוים.","title":"מידע ותפעול"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["openai-gpt","openrouter","qwen"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"למד תחילה ספק אחד לעומק, ואז השתמש ב־DeepSeek כדוגמה לבדיקת ניידות. קריאה דרך נתב היא מסלול אחר מקריאה ישירה.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"אפשר לתכנן לקוח C# באמצעות HttpClient מול HTTP API. זו דרך אינטגרציה, לא טענה שקיים SDK רשמי לכל שפה. חבילות, גרסאות וכיסוי יכולות נבדקים בנפרד לפני מימוש."}'::jsonb then raise exception 'Reviewed document changed: deepseek'; end if;
 if (select document from academy.entry_documents where slug='google-gemini') is distinct from '{"id":"google-gemini","kind":"model","name":"Google — Gemini","slug":"google-gemini","addedAt":"2026-10-31","example":"תכנון לימודי: יישום ציוד מעביר תיאור בקשה וחתימת get_stock; השרת מחזיר זמינות ורק אחר כך מנוסחת תשובה.","sources":[{"url":"https://ai.google.dev/gemini-api/docs/function-calling","title":"Google — Gemini Function Calling","supports":"הגדרת פונקציות וחיבור המודל לפעולות ולמקורות מידע. הדוגמה הארגונית היא שלנו.","checkedAt":"2026-10-31"}],"summary":"משפחת מודלים ללימוד חיבור פונקציות ליישום והפרדה בין משפחת מודלים לפלטפורמת הענן שסביבה.","exercise":"כתוב חוזה get_stock והגדר שלוש תשובות: זמין, חסר ושגיאת שירות. תוצר: טבלה המשווה את הודעות Gemini לחוזה הספק שלמדת קודם.","revision":2,"sections":[{"text":"Gemini היא משפחת מודלים של Google. Gemini API הוא ממשק גישה; פלטפורמת הענן של Google היא שכבה רחבה יותר. בחירת מודל אינה מחייבת בחירת כל תשתית הענן.","title":"מהו הפריט?"},{"text":"מגדירים פונקציות ופרמטרים, שולחים בקשה ובודקים אם המודל החזיר קריאה לפונקציה. היישום אחראי להפעלת הפעולה בהתאם לממשק שבחר ולבדיקת התוצאה.","title":"זרימת Function Calling"},{"text":"ב־React מציגים בקשה והסבר; בשרת שומרים גישה למידע ולכלים. בדומה ל־REST Controller, גם כאן חוזה קלט אינו מחליף בדיקת הרשאות או טרנזקציה.","title":"החיבור לידע שלך"},{"text":"התחל מפונקציה אחת לקריאת מלאי לפני הוספת מקורות קלט נוספים. יכולות קלט, כלים והקשר תלויות במודל ובמסלול API; אין להניח שכל גרסה תומכת באותו שילוב.","title":"מה חשוב ללמוד קודם?"},{"text":"השתמש במקרי בדיקה עם שדות חסרים ושמות פריטים עמומים. תעד את המודל ואת דרך הגישה, ובדוק תנאי מידע ועלות לפני שליחת מסמכים אמיתיים.","title":"בדיקה ותפעול"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["openai-gpt","anthropic-claude","google-vertex-ai"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"ההיכרות עם ספק שלישי נועדה ללמוד הבדלי חוזים. העמקה בפלטפורמת הענן מתאימה אחרי הבנת קריאה ישירה למודל.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"אפשר לתכנן לקוח C# באמצעות HttpClient מול HTTP API. זו דרך אינטגרציה, לא טענה שקיים SDK רשמי לכל שפה. חבילות, גרסאות וכיסוי יכולות נבדקים בנפרד לפני מימוש."}'::jsonb then raise exception 'Reviewed document changed: google-gemini'; end if;
 if (select document from academy.entry_documents where slug='google-vertex-ai') is distinct from '{"id":"google-vertex-ai","kind":"platform","name":"Google Vertex AI / Agent Platform","slug":"google-vertex-ai","addedAt":"2026-10-31","example":"תכנון לימודי: צוות בוחן גישה למודל כשירות מול פריסת מודל פתוח, ושומר את חוזה בקשת הציוד זהה.","sources":[{"url":"https://docs.cloud.google.com/gemini-enterprise-agent-platform/models","title":"Google Cloud — Models on Agent Platform","supports":"יעד ההפניה של תיעוד Vertex AI, קבוצות מודלים והבחנה בין שירות מנוהל לפריסה עצמית. התכנון העסקי הוא שלנו.","checkedAt":"2026-10-31"}],"summary":"פלטפורמת Google Cloud ללימוד בחירת מודלים וההבדל בין שירות מודלים מנוהל לפריסה עצמית.","exercise":"מפה מודל אחד מכל קבוצת קטלוג לדרך הפעלה אפשרית. תוצר: תרשים שמפריד בין מפתח המודל, מארח השירות והלקוח העסקי.","revision":2,"sections":[{"text":"קישורי Vertex AI שנבדקו מפנים לתיעוד Gemini Enterprise Agent Platform. השם Vertex AI נשמר לזיהוי חומרי לימוד קיימים. הפרק עוסק בשכבת Google Cloud סביב מודלים, ולא במשפחת Gemini עצמה.","title":"איך לזהות את המוצר?"},{"text":"תיעוד המודלים מבחין בין מודלי Google, מודלי שותפים ומודלים פתוחים, וכן בין שירות מנוהל לפריסה עצמית. לא לכל דגם יש אותן אפשרויות.","title":"מודלים ודרכי הפעלה"},{"text":"Gemini היא משפחת מודלים; פלטפורמת הענן כוללת בחירה, גישה וניהול סביב מודלים. תכנון לימודי: החלפת שכבת הגישה יכולה לשנות הזדהות ותפעול בלי לשנות את המטרה העסקית.","title":"ההבדל מ־Gemini API"},{"text":"הפרד ב־ASP.NET בין חוזה חילוץ הנתונים לבין Adapter לפלטפורמה. בממשק React מציגים תוצאה ומצב שגיאה, בלי לערב פרטי ענן בכל רכיב UI.","title":"החיבור לארכיטקטורה שלך"},{"text":"הכן טבלת אחריות למודל מנוהל מול משקלים בפריסה עצמית. בדוק אזור, הרשאות ותמיכה במודל לפני ניסוי. אין בפרק התחייבות לשם או לחבילת SDK שיישארו קבועים.","title":"בחירת מסלול"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["google-gemini","amazon-bedrock","microsoft-foundry"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"Foundry ו־Bedrock מלמדים חלופות בעננים אחרים. למסלול ראשון בחר פלטפורמה אחת להעמקה והכר את האחרות ברמה מושגית.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"אפשר לתכנן לקוח C# באמצעות HttpClient מול HTTP API. זו דרך אינטגרציה, לא טענה שקיים SDK רשמי לכל שפה. חבילות, גרסאות וכיסוי יכולות נבדקים בנפרד לפני מימוש."}'::jsonb then raise exception 'Reviewed document changed: google-vertex-ai'; end if;
 if (select document from academy.entry_documents where slug='hugging-face') is distinct from '{"id":"hugging-face","kind":"platform","name":"Hugging Face — Inference Providers","slug":"hugging-face","addedAt":"2026-10-31","example":"תרחיש לימודי: אותו סט בקשות ציוד נשלח לשני מודלים שנבחרו לבדיקה, והפלט נבדק מול טבלת אמת בלי לבצע פעולות עסקיות.","sources":[{"url":"https://huggingface.co/docs/inference-providers/index","title":"Hugging Face — Inference Providers","supports":"מודלים אצל ספקים שונים, ניתוב ולקוחות Python/JavaScript. שיטת ההערכה והטבלה הן המלצות לימודיות.","checkedAt":"2026-10-31"}],"summary":"שכבת גישה למודלים שמופעלים אצל ספקי הסקה שונים; חשוב להבחין בין המודל, הספק והפלטפורמה.","exercise":"בנה טבלה עם עמודות מודל, ספק, SDK, משימה ומדיניות נתונים. תוצר: שני מועמדים והסבר אילו פרטים נדרשים לפני העברת מידע ארגוני.","revision":2,"sections":[{"text":"Inference Providers נותנת גישה למודלים דרך ספקי הסקה ואינטגרציה בלקוחות JavaScript ו־Python. Hugging Face היא הפלטפורמה; המודל הוא רכיב נפרד, והספק הוא שמפעיל את ההסקה בפועל.","title":"מה היא פותרת?"},{"text":"היישום בוחר מודל וספק או מדיניות ניתוב, שולח קלט ומקבל תוצאה. חלק מהבדלי פורמט הבקשות מטופלים בלקוחות הרשמיים. זה לא מבטיח שכל ספק תומך בכל משימה.","title":"זרימת בקשה"},{"text":"שכבת API אחידה יכולה לצמצם קוד חיבור. עם זאת, חוזה תחבירי דומה אינו מוכיח זהות בתוצאות, זמני תגובה או מדיניות נתונים. שים את הבחירה מאחורי שירות יישומי קטן.","title":"החיבור ל־REST"},{"text":"המלצה: השתמש בסט דוגמאות שלך, למשל חילוץ בקשות בעברית. מדוד נכונות, פלט חסר והצורך בתיקון. אל תבחר לפי שם משפחה בלבד או לפי הדגמה יחידה.","title":"איך בוחרים מודל?"},{"text":"בדוק לאיזה ספק עובר המידע, רישוי המודל וזמינות משימה ספציפית. השווה עלות כוללת לקריאה מוצלחת, כולל ניסיונות חוזרים. מחירים ומכסות לא נכללים בעמוד זה.","title":"אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["llm-fundamentals","ollama","pytorch"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"HTTP, מודלי שפה והבדל בין API למודל.","alternativesNote":"API ישיר של ספק או הרצה מקומית הם מסלולים נוספים. Ollama ו־Inference Providers נמצאים בשכבות שונות ויש להשוות לפי צורך תפעולי.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"התיעוד שנבדק מציג לקוחות רשמיים ב־Python וב־JavaScript. שימוש ב־C# דרך HTTP הוא אינטגרציה, ולא הוכחה ל־SDK מקביל בשפה."}'::jsonb then raise exception 'Reviewed document changed: hugging-face'; end if;
 if (select document from academy.entry_documents where slug='llama-cpp') is distinct from '{"id":"llama-cpp","kind":"runtime","name":"llama.cpp","slug":"llama-cpp","addedAt":"2026-10-31","example":"תכנון לימודי: משווים שתי גרסאות כימות של דגם נתמך על חילוץ פרטי ציוד ובודקים איכות לצד זיכרון וזמן.","sources":[{"url":"https://github.com/ggml-org/llama.cpp","title":"ggml-org — llama.cpp","supports":"מנוע C/C++, שרת תואם API, כימות ותמיכה בחומרה. השוואת הניסוי היא שלנו.","checkedAt":"2026-10-31"}],"summary":"מנוע הסקה ללימוד פורמט מודל, כימות והקשר בין משקלים, זיכרון וחומרת הרצה.","exercise":"בנה תבנית ניסוי עם דגם קבוע ושתי רמות כימות. תוצר: שדות מדידה וקריטריון הצלחה; אין כאן תוצאות Benchmark שבוצע.","revision":2,"sections":[{"text":"llama.cpp הוא מנוע הסקה ב־C/C++, ואינו משפחת Llama של Meta. הוא תומך במגוון מודלים וחומרות לפי תיעוד התאימות; שם הפרויקט אינו מגביל אותו למודלי Llama.","title":"הבדל השמות החשוב"},{"text":"המנוע טוען משקלים בפורמט נתמך ומבצע הסקה. כלי שורת פקודה ושרת API הם דרכי הפעלה סביבו. אלה רכיבים שונים מהלקוח ששולח Prompt.","title":"איך שכבת המנוע עובדת?"},{"text":"התיעוד מתאר כימות במספר רמות ושילוב CPU ו־GPU. כימות משנה את ייצוג המשקלים ויכול להפחית צריכת זיכרון; השפעתו על איכות ומהירות דורשת מדידה.","title":"כימות ומשאבים"},{"text":"תכנון לימודי: צריכת שרת HTTP שומרת את הקוד העסקי ב־C#. שימוש ישיר בספריית C++ הוא מסלול אינטגרציה אחר עם אחריות נוספת, ולא חובה לתרגיל הראשון.","title":"החיבור ל־.NET"},{"text":"החזק את המשימה קבועה ותעד דגם, פורמט, כימות וחומרה. אל תייחס שינוי באיכות לספק אם באותו זמן שינית גם את ייצוג המשקלים או תצורת ההרצה.","title":"איך בודקים?"}],"verifiedAt":"2026-10-31","categoryIds":["08"],"addedAtBasis":"historical_backfill","relatedSlugs":["meta-llama","ollama","vllm"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, HTTP והבחנה בין זיכרון RAM לזיכרון GPU.","alternativesNote":"Ollama ו־LM Studio נוחים ללימוד סביבת עבודה; vLLM מתמקד בהגשת מודלים ובניהול בקשות.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"המנוע כתוב ב־C/C++; שרת API מאפשר אינטגרציה ב־C#, Python ו־TypeScript באמצעות HTTP. אין כאן טענת SDK רשמי לשפות אלה."}'::jsonb then raise exception 'Reviewed document changed: llama-cpp'; end if;
 if (select document from academy.entry_documents where slug='llm-fundamentals') is distinct from '{"id":"llm-fundamentals","kind":"concept","name":"מודלי שפה — יסודות","slug":"llm-fundamentals","addedAt":"2026-10-31","example":"תרחיש לימודי: בקשה חופשית לציוד הופכת להצעת JSON עם קוד פריט וכמות. השרת בודק את ההצעה ורק אז מחפש מלאי; אין ביצוע הזמנה רק משום שהטקסט נשמע בטוח.","sources":[{"url":"https://developers.google.com/machine-learning/crash-course/llm","title":"Google — מבוא למודלי שפה","supports":"מודל הסתברותי, Tokens ויצירת טקסט. דפוסי התכנון, הדוגמאות והתרגילים הם הסבר לימודי שלנו.","checkedAt":"2026-10-31"}],"summary":"הבנת Tokens, הקשר והסקה: הבסיס לבחירת מודל ולבניית יישום שמשתמש בו.","exercise":"כתוב שלוש בקשות ציוד: ברורה, עמומה וסותרת. הגדר פלט צפוי ומתי חייבים לשאול שאלת הבהרה. תוצר: טבלת מקרי בדיקה שהיית מפעיל על כל מודל מועמד.","revision":2,"sections":[{"text":"מודל שפה מעריך הסתברויות לרצפי Tokens. Token יכול להיות מילה, חלק ממילה או תו. ביצירת טקסט המודל מפיק המשך על בסיס הקלט; ניסוח משכנע אינו הוכחה לנכונות.","title":"מהו מודל שפה?"},{"text":"יישום מרכיב הוראות, שאלה ומידע רלוונטי, שולח אותם למודל ומקבל פלט. בהסקה משתמשים במודל קיים; באימון משנים את פרמטרי המודל. הוספת טקסט לשאלה אינה אימון.","title":"זרימת עבודה בסיסית"},{"text":"חשוב על שירות שמחזיר הצעה שדורשת בדיקה. JSON תקין הוא חוזה מבני בלבד: מספר פריט שנראה תקין עדיין צריך להיבדק ב־SQL מול הנתונים והרשאות המשתמש.","title":"החיבור לידע שלך"},{"text":"המלצה הנדסית: תן למודל לעבד שפה לא מובנית, והשאר חישוב סכומים ובדיקת מלאי לקוד דטרמיניסטי. הגדר מראש מהי תשובה נכונה ומה עושים כשחסר מידע.","title":"איך לבחור שימוש נכון?"},{"text":"תכנן מה מותר להעביר לספק, כמה קלט דרוש ומתי לעצור. אל תסיק ממספר המילים את מספר ה־Tokens בעברית. גודל ההקשר והמחיר תלויים במודל ונבדקים לפני שימוש.","title":"אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["00","07"],"addedAtBasis":"historical_backfill","relatedSlugs":["hugging-face","ollama","llamaindex"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"פונקציות, JSON וקריאת API.","alternativesNote":"לפני שימוש במודל, בדוק אם כללים, חיפוש רגיל או טופס מובנה פותרים את הבעיה באופן פשוט יותר.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"זהו מושג, לא SDK. אפשר לצרוך מודל מ־C#, Python או TypeScript דרך ממשק שהספק מציע; יש לבדוק כל SDK בנפרד."}'::jsonb then raise exception 'Reviewed document changed: llm-fundamentals'; end if;
 if (select document from academy.entry_documents where slug='lm-studio') is distinct from '{"id":"lm-studio","kind":"product","name":"LM Studio","slug":"lm-studio","addedAt":"2026-10-31","example":"תכנון לימודי: בוחנים בקשת ציוד בממשק, ואז מתכננים קריאה לאותו מודל מתוך שירות HTTP מקומי.","sources":[{"url":"https://lmstudio.ai/docs/app","title":"LM Studio — App documentation","supports":"יישום, הורדת מודל וקישורי דרישות מערכת ועבודה לא מקוונת.","checkedAt":"2026-10-31"},{"url":"https://lmstudio.ai/docs/developer","title":"LM Studio — Developer documentation","supports":"שרת, REST API ומסלולי פיתוח. תכנון אינטגרציית C# הוא שלנו.","checkedAt":"2026-10-31"}],"summary":"יישום להרצת מודלים מקומיים ולימוד בחירת מודל וצריכתו דרך שרת מקומי לפני ניהול תשתית מורכבת.","exercise":"תעד בנפרד קובץ מודל, מנוע, שרת ולקוח. תוצר: תרשים בקשה ורשימת בדיקות התאמה לחומרה; הרצה בפועל היא תרגול עתידי.","revision":2,"sections":[{"text":"LM Studio מאפשר להוריד מודלים ולהריץ אותם דרך יישום מקומי. זהו כלי עבודה סביב מודלים קיימים, ולא משפחת מודלים. הוא מתאים להיכרות חזותית עם שכבת ההרצה.","title":"מה הוא פותר?"},{"text":"תיעוד הפיתוח מציג שרת ו־REST API. ההפרדה הלימודית: שיחה בממשק היא לקוח אחד; יישום שאתה מפתח הוא לקוח נוסף שיכול לצרוך את השרת.","title":"מהממשק לשרת"},{"text":"בדוק את דרישות המערכת ואת התאמת הדגם למנוע ולזיכרון. הורדה מוצלחת אינה הוכחה לזמן תגובה שימושי או לאיכות טובה בעברית.","title":"בחירת דגם וחומרה"},{"text":"תכנון לימודי: ASP.NET משתמש ב־HttpClient מול שרת מקומי ומחזיר DTO. אין צורך להטמיע את ממשק LM Studio בתוך React כדי ללמוד אינטגרציה.","title":"החיבור ל־C#"},{"text":"פעולות הורדה דורשות גישה למקורות חיצוניים. בדוק מצב עבודה לא מקוון, כתובת שרת וכלים מחוברים לפני מידע רגיש. שרת מקומי שנחשף לרשת צריך בקרת גישה.","title":"מקומי ופרטיות"}],"verifiedAt":"2026-10-31","categoryIds":["08"],"addedAtBasis":"historical_backfill","relatedSlugs":["ollama","llama-cpp","qwen"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, HTTP והבחנה בין זיכרון RAM לזיכרון GPU.","alternativesNote":"Ollama הוא מסלול נוסף ללימוד API מקומי; llama.cpp מעמיק בשכבת המנוע ו־vLLM בשירות מקבילי.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"אפשר לתכנן לקוח C# באמצעות HttpClient מול HTTP API. זו דרך אינטגרציה, לא טענה שקיים SDK רשמי לכל שפה. חבילות, גרסאות וכיסוי יכולות נבדקים בנפרד לפני מימוש."}'::jsonb then raise exception 'Reviewed document changed: lm-studio'; end if;
 if (select document from academy.entry_documents where slug='meta-llama') is distinct from '{"id":"meta-llama","kind":"model","name":"Meta — Llama","slug":"meta-llama","addedAt":"2026-10-31","example":"תכנון לימודי: אותו מנתח בקשות ציוד משתמש פעם בשירות חיצוני ופעם בדגם Llama שמוגש בשרת בשליטת הארגון.","sources":[{"url":"https://github.com/meta-llama/llama-models","title":"Meta — Llama Models","supports":"הגדרת Llama, זמינות משקלים, כרטיסי דגמים ורישיונות. תכנון הפריסה הוא לימודי.","checkedAt":"2026-10-31"}],"summary":"משפחת מודלים עם משקלים זמינים ללימוד ההבדל בין בעלות על סביבת הריצה לשימוש בשירות חיצוני.","exercise":"בחר כרטיס דגם רשמי ורשום רישיון, גודל, פורמט ומנוע יעד. תוצר: דף התאמה לחומרה ולמשימה, ללא צורך להוריד מודל גדול.","revision":2,"sections":[{"text":"Meta היא המפתחת ו־Llama היא משפחת מודלים. llama.cpp הוא מנוע הרצה נפרד, ו־Ollama הוא כלי נוסף להרצת מודלים. דמיון בשמות אינו אומר שזה אותו רכיב.","title":"מודל לעומת מנוע הרצה"},{"text":"המאגר הרשמי מפרסם מידע וקישורים למודלים ולרישיונות. זמינות משקלים אינה מעניקה רישיון אחיד או מבטיחה שהמודל ירוץ במחשב שלך. בדוק תנאים של הדגם המדויק.","title":"מה המשמעות של משקלים זמינים?"},{"text":"בחר דגם ופורמט נתמכים, בדוק זיכרון, טען במנוע מתאים והנגש שירות ליישום. האחריות לתפעול המנוע ולבחירת המודל עוברת אליך; משקלים לבדם אינם API.","title":"זרימת עבודה עצמאית"},{"text":"תכנון לימודי: ASP.NET מדבר עם שרת הסקה דרך מתאם HTTP, בדומה לשירות תשתיתי נפרד. ההיגיון העסקי נשאר ב־C#; אין צורך להעביר אותו לשפת המנוע.","title":"החיבור ל־.NET"},{"text":"למד למדוד איכות בעברית, זמן תגובה וזיכרון על אותה משימה. הרצה עצמאית אינה הוכחה לפרטיות: גם רשת, לוגים וכלים מחוברים משפיעים על זרימת המידע.","title":"מדידה ורישוי"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["ollama","llama-cpp","qwen"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"Qwen ו־Mistral מספקים נקודות השוואה. השווה דגמים מסוימים ורישיונות, ולא רק שמות משפחות.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"המודל אינו SDK לשפת תכנות. Python, C# ו־TypeScript יכולים לצרוך שרת מתאים; תמיכה תלויה במנוע ובחוזה שלו."}'::jsonb then raise exception 'Reviewed document changed: meta-llama'; end if;
 if (select document from academy.entry_documents where slug='microsoft-foundry') is distinct from '{"id":"microsoft-foundry","kind":"platform","name":"Microsoft Foundry (Azure AI Foundry)","slug":"microsoft-foundry","addedAt":"2026-10-31","example":"תכנון לימודי: יישום ארגוני קורא למודל דרך שירות Azure עם זהות שירות, בעוד בדיקות המלאי והאישור נשארות ב־API העסקי.","sources":[{"url":"https://learn.microsoft.com/en-us/azure/foundry/what-is-foundry","title":"Microsoft — What is Microsoft Foundry?","supports":"שם המוצר, מודלים וכלים, RBAC ורשת; חלק מהיכולות ב־Preview. תכנון .NET הוא שלנו.","checkedAt":"2026-10-31"}],"summary":"פלטפורמת Azure ללימוד גישה למודלים, ניהול הרשאות והפרדה בין שירות ענן למסגרת פיתוח סוכנים.","exercise":"צייר React, שרת ASP.NET, שכבת זהות ופלטפורמת מודלים. תוצר: רשימת הרשאות לכל רכיב והסבר ההבדל בין Foundry ל־Agent Framework.","revision":2,"sections":[{"text":"התיעוד הרשמי שנבדק מציג את Microsoft Foundry; השם Azure AI Foundry נשמר כאן לזיהוי. זו פלטפורמת ניהול למודלים, כלים וסוכנים, ולא מודל שפה.","title":"שם והגדרה"},{"text":"קטלוג מודלים מאפשר לבחור מודל בלי לבלבל בין המפתח שלו לפלטפורמה שמנגישה אותו. זמינות דגם ותכונות נבדקת לפי המסלול והמשאב המסוימים.","title":"מודל מול פלטפורמה"},{"text":"התיעוד מתאר ניהול באמצעות RBAC, רשת ומדיניות. המשמעות הלימודית היא שגישה למודל בארגון כוללת זהות והרשאות לצד בקשת JSON.","title":"זהות, רשת ומדיניות"},{"text":"Microsoft Agent Framework הוא מסגרת קוד; Foundry היא פלטפורמת ענן. שירות .NET יכול להשתמש במודל בלי שהמושגים יתמזגו. יש לבחור בנפרד חוזה פיתוח וסביבת הפעלה.","title":"החיבור ל־C#"},{"text":"הכן תרשים משאבים והרשאות עם נתוני דוגמה. אין צורך לפתוח חשבון או לפרוס פרויקט כדי להבין את ההפרדה. יכולות Preview אינן הבטחה לזמינות כללית.","title":"איך לומדים בלי להקים ענן?"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["microsoft-agent-framework","openai-gpt","amazon-bedrock"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"Bedrock ופלטפורמת Google Cloud הן חלופות ללימוד עקרונות ענן. היכרות אינה החלטה להעביר את הפרויקט ל־Azure.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"אפשר לתכנן לקוח C# באמצעות HttpClient מול HTTP API. זו דרך אינטגרציה, לא טענה שקיים SDK רשמי לכל שפה. חבילות, גרסאות וכיסוי יכולות נבדקים בנפרד לפני מימוש."}'::jsonb then raise exception 'Reviewed document changed: microsoft-foundry'; end if;
 if (select document from academy.entry_documents where slug='mistral-ai') is distinct from '{"id":"mistral-ai","kind":"model","name":"Mistral AI","slug":"mistral-ai","addedAt":"2026-10-31","example":"תכנון לימודי: צוות בוחן חילוץ שדות מבקשת ציוד דרך API ובונה בנפרד הערכת אחריות להרצה עצמית.","sources":[{"url":"https://docs.mistral.ai/","title":"Mistral AI — Documentation","supports":"Studio ו־API, קטלוג דגמים ורישיונות שונים. ניתוח הבחירה הוא שלנו.","checkedAt":"2026-10-31"}],"summary":"ספק מודלים ללימוד ההבחנה בין API מסחרי, דגמים במשקלים זמינים ומוצרי קצה.","exercise":"בחר שני דגמים מתוך התיעוד הרשמי ותעד מפתח, רישיון ודרך גישה. תוצר: טבלת הבדלים המבחינה בין ספק המודל לספק האירוח.","revision":2,"sections":[{"text":"Mistral AI מפעילה פלטפורמה ומפתחת מודלים. הקטלוג מציג דגמים ורישיונות שונים; אין להציג את כל המוצרים כמשפחה בעלת אותו רישיון או אותו ממשק.","title":"מהו הספק ומהו המודל?"},{"text":"התיעוד מציג API דרך סביבת Studio לצד מודלים עם משקלים זמינים. בחירת שירות מנוהל ובחירת הרצה עצמאית הן החלטות תפעוליות שונות גם כששם המודל דומה.","title":"דרכי גישה"},{"text":"תכנון לימודי: מתאם שירות ממיר בקשת DTO לחוזה הספק. אם בוחרים משקלים להרצה עצמית, מתווספת אחריות לשרת הסקה, זמינות וחומרה.","title":"החיבור ל־REST"},{"text":"בדוק אם הדגם שייך לספק עצמו או לצד שלישי, מה המשימה שלו ומה הרישיון. קטלוג פלטפורמה אינו רשימת מודלים שכולם פותחו על ידה.","title":"מה בודקים בקטלוג?"},{"text":"בחר משימה קבועה ובחן פלט, מידע ועלות כוללת. אין כאן קביעת יתרון בביצועים או אישור שכל דגם מתאים לשימוש מסחרי ללא תנאים.","title":"שיקולי בחירה"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["qwen","meta-llama","together-ai"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"השווה מול Qwen או Llama כאשר נדרשים משקלים; מול ספקי API אחרים כשנדרש שירות מנוהל.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"אפשר לתכנן לקוח C# באמצעות HttpClient מול HTTP API. זו דרך אינטגרציה, לא טענה שקיים SDK רשמי לכל שפה. חבילות, גרסאות וכיסוי יכולות נבדקים בנפרד לפני מימוש."}'::jsonb then raise exception 'Reviewed document changed: mistral-ai'; end if;
 if (select document from academy.entry_documents where slug='ollama') is distinct from '{"id":"ollama","kind":"runtime","name":"Ollama","slug":"ollama","addedAt":"2026-10-31","example":"תרחיש לימודי: סיווג פניות דוגמה במחשב מקומי והשוואתן לתוצאות של שירות מרוחק, ללא העברת מידע אמיתי לפני בדיקת מדיניות.","sources":[{"url":"https://docs.ollama.com/api/introduction","title":"Ollama — API Introduction","supports":"API מקומי וענן, כתובות שרת וספריות רשמיות Python/JavaScript. תכנון Adapter והתרגיל הם שלנו.","checkedAt":"2026-10-31"}],"summary":"כלי להרצת מודלים ולגישה אליהם דרך API; יש להבחין בין הרצה מקומית לשימוש במודלי ענן.","exercise":"שרטט לקוח, שרת ומודל, וסמן את מסלול המידע המקומי לעומת ענן. תוצר: בדיקות כתובת יעד, זמני תגובה ותגובה כאשר המודל אינו זמין.","revision":2,"sections":[{"text":"Ollama מאפשר להריץ מודלים במחשב ולצרוך אותם מתוך יישום. התיעוד מתאר גם גישה למודלי ענן. לכן השם Ollama לבדו אינו אומר שהמידע נשאר מקומי.","title":"מה הוא פותר?"},{"text":"מורידים מודל מתאים, מפעילים שרת מקומי והיישום שולח בקשות HTTP. המודל, השרת והלקוח הם רכיבים שונים. התאמת המודל לחומרה נבדקת לפי משאבים וביצועים בפועל.","title":"זרימת עבודה מקומית"},{"text":"אפשר לתכנן Adapter עם HttpClient שמסתיר כתובת שרת ופורמט פלט משאר היישום. החלפת שרת או מודל צריכה לדרוש שינוי ממוקד ובדיקות, ולא לפזר תנאים בכל Controller.","title":"החיבור ל־C#"},{"text":"המלצה: ניסויים מקומיים, למידת שכבת ההסקה או צורך מוגדר בשליטה על סביבת הריצה. השווה איכות, זמן תגובה וצריכת זיכרון; מקומי אינו בהכרח מהיר או זול יותר.","title":"מתי לבחור?"},{"text":"בדוק שהמודל והכתובת אכן מקומיים ושאין הפניה לענן. אל תחשוף את השרת לרשת ללא בקרת גישה. עלות כוללת כוללת חומרה ותפעול, לא רק מחיר בקשת API.","title":"אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["08"],"addedAtBasis":"historical_backfill","relatedSlugs":["hugging-face","llm-fundamentals"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"HTTP, תהליכים מקומיים והיכרות בסיסית עם משאבי מחשב.","alternativesNote":"llama.cpp, vLLM ו־LM Studio מופיעים במפת הידע. יש לבדוק בנפרד את התאמתם לחומרה, למודל ולפריסה; לא בוצע כאן Benchmark.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"התיעוד מציג ספריות רשמיות ל־Python ול־JavaScript ו־API ללקוחות HTTP. ב־C# אפשר להתחבר ב־HTTP; זה אינו אישור ללקוח רשמי מסוים."}'::jsonb then raise exception 'Reviewed document changed: ollama'; end if;
 if (select document from academy.entry_documents where slug='openai-gpt') is distinct from '{"id":"openai-gpt","kind":"model","name":"OpenAI — GPT","slug":"openai-gpt","addedAt":"2026-10-31","example":"תכנון לימודי: בקשת ציוד הופכת ל־DTO עם itemId ו־quantity; שרת ASP.NET בודק מלאי ומחזיר הצעה לאישור.","sources":[{"url":"https://developers.openai.com/api/docs/guides/structured-outputs","title":"OpenAI — Structured Outputs","supports":"סכמת פלט, הבחנה מול Function Calling וסירוב או פלט חלקי. התכנון והתרגיל הם שלנו.","checkedAt":"2026-10-31"}],"summary":"משפחת מודלים ללימוד עבודה עם API, פלט מובנה והפרדה בין הצעת מודל לפעולה עסקית.","exercise":"הכן סכמת בקשת ציוד ועשרה מקרי בדיקה, כולל מזהה מומצא, כמות שלילית וסירוב. תוצר: טבלת פלט צפוי ומדיניות טיפול בפלט חסר; אין צורך בקריאת API בתשלום.","revision":2,"sections":[{"text":"OpenAI היא הספקית ו־GPT הוא שם משפחת מודלים. הפרק עוסק במודל ובשימוש בו דרך API; מוצר ChatGPT וערכת Agents SDK הם שכבות נפרדות. מטרת הלימוד היא להבין חוזה קלט ופלט לפני שמוסיפים מסגרת סוכנים.","title":"מה לומדים ולמה?"},{"text":"Structured Outputs מגביל פלט לסכמת JSON נתמכת. Function Calling משמש לחיבור לפונקציות ולמידע של היישום. פלט שעומד בסכמה עדיין עלול להכיל קוד פריט שאינו קיים; יש לטפל גם בסירוב ובתשובה שנקטעה.","title":"פלט מובנה לעומת בקשת כלי"},{"text":"תכנון לימודי: Controller מקבל בקשה, שירות מודל מציע DTO, ו־Validator בודק כמות ומזהה מול SQL. חוזה מבני דומה לבדיקת טיפוסים; נכונות עסקית מחייבת בדיקה נוספת.","title":"החיבור ל־C# ול־SQL"},{"text":"השתמש באותו אוסף בקשות בעברית ובאנגלית והשווה חילוץ שדות, בקשת הבהרה וזמן תגובה. בחירת משפחה אינה בחירת גרסה; רשום מזהה מודל ותצורת בקשה לכל ניסוי.","title":"איך בוחנים התאמה?"},{"text":"הגדר הרשאות, מגבלת ניסיונות ותקרת שימוש לפני חיבור למערכת עסקית. המפתח נשמר בשרת. דוגמה לימודית אינה הרשאה להזמין ציוד או לעדכן נתונים.","title":"אחריות היישום"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["anthropic-claude","google-gemini","openai-agents-sdk"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"השווה Claude ו־Gemini באותה משימה. Agents SDK נלמד בנפרד כשנדרשת לולאת סוכן; אין צורך בו רק כדי לקבל JSON.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"אפשר לתכנן לקוח C# באמצעות HttpClient מול HTTP API. זו דרך אינטגרציה, לא טענה שקיים SDK רשמי לכל שפה. חבילות, גרסאות וכיסוי יכולות נבדקים בנפרד לפני מימוש."}'::jsonb then raise exception 'Reviewed document changed: openai-gpt'; end if;
 if (select document from academy.entry_documents where slug='openrouter') is distinct from '{"id":"openrouter","kind":"platform","name":"OpenRouter","slug":"openrouter","addedAt":"2026-10-31","example":"תכנון לימודי: בודקים עשר בקשות ציוד מול שני מודלים דרך נתב, ושומרים תוצאה וזהות שירות לצורך השוואה.","sources":[{"url":"https://openrouter.ai/docs/quickstart","title":"OpenRouter — Quickstart","supports":"API משותף למודלים, מסלולי אינטגרציה וקישורי ניתוב. מדיניות היישום היא שלנו.","checkedAt":"2026-10-31"}],"summary":"פלטפורמת גישה למודלים דרך API משותף ללימוד ניתוב והפרדה בין ספק המודל לספק השירות.","exercise":"צייר בקשה ישירה ובקשה דרך נתב. תוצר: מדיניות fallback עם רשימת ספקים מותרת ותנאי עצירה כשהמודל החלופי אינו תומך בחוזה.","revision":2,"sections":[{"text":"OpenRouter נותנת גישה למודלים דרך נקודת API משותפת. בפרק זה היא מסווגת כפלטפורמת גישה, ולא כמשפחת LLM. היישום, הנתב והספק שמשרת את הבקשה הם רכיבים שונים.","title":"איזו שכבה זו?"},{"text":"יישום שולח בקשה עם בחירת מודל, והפלטפורמה מנתבת לשירות מתאים לפי הגדרותיה. חשוב להבין מי משרת את הבקשה ולא להסתפק בשם המודל שהלקוח ביקש.","title":"זרימת בקשה"},{"text":"הקבלה לימודית: API Gateway שמוסיף ניתוב מול כמה שירותים. Adapter יחיד ב־C# יכול לפשט גישה, אך אינו מבטל הבדלים בין כלים, פלט ושגיאות של מודלים שונים.","title":"החיבור ל־.NET"},{"text":"אחרי קריאה ישירה לספק אחד, השתמש בנתב כדי להבין ניידות והשוואה. תכנון fallback צריך להגדיר אילו ספקים מותרים ואילו תכונות חייבות להישמר.","title":"מתי ללמוד ולמה?"},{"text":"בדוק מדיניות של הפלטפורמה ושל ספקי ההמשך. תעד מודל וספק בפועל כשזמין. מעבר אוטומטי שאינו עומד בדרישות מידע או חוזה צריך להיחסם בתכנון היישום.","title":"מידע ואמינות"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["openai-gpt","hugging-face","together-ai"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"גישה ישירה מפחיתה שכבת תיווך; נתב מפשט ניסויים בין שירותים. Hugging Face ו־Together מייצגים מסלולי גישה נוספים.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"אפשר לתכנן לקוח C# באמצעות HttpClient מול HTTP API. זו דרך אינטגרציה, לא טענה שקיים SDK רשמי לכל שפה. חבילות, גרסאות וכיסוי יכולות נבדקים בנפרד לפני מימוש."}'::jsonb then raise exception 'Reviewed document changed: openrouter'; end if;
 if (select document from academy.entry_documents where slug='qwen') is distinct from '{"id":"qwen","kind":"model","name":"Alibaba — Qwen","slug":"qwen","addedAt":"2026-10-31","example":"תכנון לימודי: בוחנים שני גדלים נתמכים מאותה משפחה על חילוץ itemId וכמות, עם אותו סט בקשות.","sources":[{"url":"https://qwen.readthedocs.io/en/latest/","title":"Qwen — Official documentation","supports":"זהות המשפחה, מגוון דגמים וקישורי הרצה ופריסה. מטריצת הבחירה היא שלנו.","checkedAt":"2026-10-31"}],"summary":"משפחת מודלים ללימוד בחירת דגם, תצורת הסקה והתאמה למנועי הרצה שונים.","exercise":"בנה מטריצה לשני דגמים: משימה, רישיון, מנוע אפשרי ומשאבים לבדיקה. תוצר: בחירה מנומקת לניסוי ראשון, בלי להכריז על מנצח לפני מדידה.","revision":2,"sections":[{"text":"Qwen היא משפחת מודלים של צוות Qwen בקבוצת Alibaba. התיעוד מתאר מודלי שפה ומודלים רב־מודליים. השם המשפחתי אינו חוזה יכולות אחיד לכל דגם.","title":"מה חשוב לזהות?"},{"text":"בחירת דגם כוללת גודל, סוג משימה ומצב הסקה נתמך. אל תסיק שתמיכה בקוד או בכלים בדגם אחד חלה על כולם. כרטיס הדגם ותיעוד המנוע הם נקודת הבדיקה.","title":"משפחה, דגם ותצורה"},{"text":"התיעוד מפנה ל־Transformers, Ollama, llama.cpp ו־vLLM. אלה דרכי הרצה שונות לאותה משפחה, בכפוף לתאימות. יש להפריד בין הורדת המשקלים לבין שירות בקשות מקבילות.","title":"איך מריצים?"},{"text":"תכנון לימודי: ממשק C# משותף מחזיר הצעת בקשת ציוד בלי לחשוף את סוג המנוע ל־Controller. שמור לצד התוצאה מזהה דגם ותצורה כדי שתוכל לשחזר כשל.","title":"החיבור למערכת עסקית"},{"text":"איכות בעברית, התאמה לחומרה ורישיון מסחרי נבדקים לדגם המסוים. טענות ביצועים של הספק הן בסיס לתכנון ניסוי, ולא תוצאת ניסוי בפרויקט שלנו.","title":"מה לא להסיק מהשם?"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["meta-llama","ollama","vllm"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"Llama ו־Mistral הם חלופות להשוואת משקלים זמינים. אין כאן המלצה להתקין את כל מנועי ההרצה.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"משפחת מודלים, ללא SDK C# בפני עצמה. האינטגרציה לשפות היישום נקבעת לפי שרת ההסקה או ספק האירוח."}'::jsonb then raise exception 'Reviewed document changed: qwen'; end if;
 if (select document from academy.entry_documents where slug='together-ai') is distinct from '{"id":"together-ai","kind":"platform","name":"Together AI","slug":"together-ai","addedAt":"2026-10-31","example":"תכנון לימודי: אותו שירות חילוץ נתונים משתמש במודל דרך שירות מנוהל, ומושווה בתכנון לשרת עצמאי.","sources":[{"url":"https://docs.together.ai/intro","title":"Together AI — Overview","supports":"הסקה, API תואם, Fine-tuning ואשכולות GPU. השוואת האחריות היא שלנו.","checkedAt":"2026-10-31"}],"summary":"פלטפורמת הסקה ואימון ללימוד שימוש במודלים קיימים בשירות מנוהל במקום ניהול חומרה עצמאי.","exercise":"הכן טבלת אחריות עבור API מנוהל מול שרת עצמי: עדכונים, קיבולת, הרשאות וניטור. תוצר: החלטה מנומקת למסלול ניסוי בלי להקים משאבים.","revision":2,"sections":[{"text":"Together AI מאפשרת להריץ, להתאים ולהגיש מודלים. זהו פרק על תשתית שירות למודלים קיימים, ולא על משפחת מודלים אחת.","title":"מה היא מספקת?"},{"text":"התיעוד מפריד בין הסקה Serverless, הסקה ייעודית, Fine-tuning ואשכולות GPU. אלה רמות אחריות וקיבולת שונות; אין צורך ללמוד או לרכוש את כולן כדי להתנסות ב־API.","title":"מסלולי הפעלה"},{"text":"תכנון לימודי: ASP.NET שולח בקשות למודל מאחורי שירות מנוהל. בהשוואה ל־vLLM עצמאי, חלק מתפעול החומרה עובר לספק, אך בדיקת הפלט נשארת ביישום.","title":"החיבור למערכת קיימת"},{"text":"השווה דרך גישה, מגבלות, זמינות ותאימות לדגם נבחר. ממשק תואם אינו מבטיח שכל תכונה של לקוח אחר נתמכת. דגם שמופיע בקטלוג עשוי להגיע ממפתח אחר.","title":"מה לומדים מההשוואה?"},{"text":"Fine-tuning הוא מסלול נפרד. התחל מבסיס בדיקות ו־Prompt לפני אימון. יש לבדוק פרטיות, תנאי משקלים ועלות זמן סרק לפני בחירת משאב ייעודי.","title":"התאמה אינה ברירת מחדל"}],"verifiedAt":"2026-10-31","categoryIds":["07"],"addedAtBasis":"historical_backfill","relatedSlugs":["openrouter","vllm","mistral-ai"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, JSON, REST ואימות קלט בצד השרת.","alternativesNote":"OpenRouter הוא דוגמה לשכבת גישה; vLLM למנוע בהפעלה עצמית. אין כאן השוואת מחירים ביניהם.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"אפשר לתכנן לקוח C# באמצעות HttpClient מול HTTP API. זו דרך אינטגרציה, לא טענה שקיים SDK רשמי לכל שפה. חבילות, גרסאות וכיסוי יכולות נבדקים בנפרד לפני מימוש."}'::jsonb then raise exception 'Reviewed document changed: together-ai'; end if;
 if (select document from academy.entry_documents where slug='vllm') is distinct from '{"id":"vllm","kind":"runtime","name":"vLLM","slug":"vllm","addedAt":"2026-10-31","example":"תכנון לימודי: מספר משתמשים שולחים בקשות ציוד ל־ASP.NET, שמווסת עומס לפני העברה לשרת הסקה ארגוני.","sources":[{"url":"https://docs.vllm.ai/en/latest/","title":"vLLM — Official documentation","supports":"הסקה והגשה מקוונת, שרת תואם, התקנה, דגמים וניטור. ניסוי העומס הוא תוכנית לימודית.","checkedAt":"2026-10-31"}],"summary":"מנוע ושרת הסקה ללימוד הגשת מודלים לבקשות מקבילות והאחריות התפעולית של הרצה עצמאית.","exercise":"תכנן ניסוי של בקשה אחת מול כמה בקשות מקבילות. תוצר: טבלת מדדים הכוללת זמן המתנה, קצב, זיכרון וכשלים, בלי להקים שרת GPU.","revision":2,"sections":[{"text":"vLLM הוא מנוע ושירות הגשת מודלים. לאחר בקשה מקומית אחת, השאלה הבאה היא כיצד לשרת כמה לקוחות במשאבים נתונים. המנוע אינו המודל ואינו מסגרת סוכנים.","title":"למה ללמוד אחרי הרצה מקומית?"},{"text":"התיעוד מפריד בין הסקה לא מקוונת להגשה מקוונת וכולל שרת תואם OpenAI. יש לבדוק התאמת דגם, חומרה ותכונות; תאימות ממשק אינה שוויון מלא לשירות המקורי.","title":"מנוע ושרת"},{"text":"למד להבחין בין זמן לתשובה אחת, קצב כולל ועומס בקשות. תכנון לימודי: שיפור קצב כולל עלול לשנות זמני המתנה; יש למדוד את שניהם במקום להסתפק במספר יחיד.","title":"מקביליות ומשאבים"},{"text":"שרת היישום שולח בקשות לשרת הסקה נפרד דרך מתאם. בדומה לשירות תשתיתי, נדרשים timeout, בקרת עומס וניטור. אין צורך להעביר את הלוגיקה העסקית ל־Python.","title":"החיבור ל־ASP.NET"},{"text":"הרצה עצמאית דורשת אבטחה, ניהול זיכרון ועדכונים. בדוק את מדריך ההתקנה לחומרה ולמערכת ההפעלה שלך; פרק זה אינו טענה שפריסה מקומית ב־Windows כבר נוסתה.","title":"אחריות תפעולית"}],"verifiedAt":"2026-10-31","categoryIds":["08"],"addedAtBasis":"historical_backfill","relatedSlugs":["llama-cpp","together-ai","qwen"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"יסודות מודלי שפה, HTTP והבחנה בין זיכרון RAM לזיכרון GPU.","alternativesNote":"llama.cpp מתאים ללימוד מנוע וכימות; Together מדגים שירות מנוהל. הבחירה תלויה במשאבים ובאחריות תפעולית, ולא ביוקרת הכלי.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"תיעוד המנוע כולל Python ושרת HTTP תואם; שירות C# או TypeScript יכול לצרוך HTTP. זה אינו SDK מקומי ל־.NET."}'::jsonb then raise exception 'Reviewed document changed: vllm'; end if;
 if (select jsonb_build_object('title',title,'intro',introduction,'note',note,'steps',(select jsonb_agg(jsonb_build_object('slug',e.slug,'text',s.instruction,'label',s.link_label) order by s.position) from academy.category_guide_steps s join academy.entries e on e.id=s.entry_id where s.category_id=g.category_id)) from academy.category_guides g where category_id='07') is distinct from '{"title":"איך ללמוד את עולם המודלים?","intro":"החלוקה כאן היא לפי תפקיד במערכת. עדיפות הלימוד בפרקים היא בחירה פדגוגית שלנו, ולא דירוג נתח שוק או איכות. למד API אחד לעומק; את היתר הכר דרך השוואת אותו תרחיש.","note":"Cohere, Gemma ו־Phi נשארו להרחבה בהמשך. המטרה בסבב הזה היא להבין את השכבות לפני שמוסיפים עוד משפחות.","steps":[{"text":"בסיס: ספק ומשפחת מודלים — OpenAI/GPT, Anthropic/Claude ו־Google/Gemini. התחל מהפרק הראשון והשווה חוזי פלט וכלים.","slug":"openai-gpt","label":"להתחלה עם API ופלט מובנה"},{"text":"משקלים וסביבת ריצה — Llama ו־Qwen כבסיס; DeepSeek ו־Mistral להרחבת ההיכרות. משפחת מודלים אינה מנוע שמפעיל אותה.","slug":"meta-llama","label":"להבנת מודלים במשקלים זמינים"},{"text":"גישה ואירוח — Hugging Face, OpenRouter ו־Together AI. למד מי פיתח את המודל ומי משרת את הבקשה בפועל.","slug":"openrouter","label":"להבנת שכבת הגישה"},{"text":"ענן ארגוני — Microsoft Foundry, Amazon Bedrock ו־Google Vertex AI / Agent Platform. הכר את שלושתם ובחר אחד להעמקה לפי סביבת העבודה שלך.","slug":"microsoft-foundry","label":"למודלים, זהות והרשאות בענן"}]}'::jsonb then raise exception 'Reviewed guide changed: 07'; end if;
 if (select jsonb_build_object('title',title,'intro',introduction,'note',note,'steps',(select jsonb_agg(jsonb_build_object('slug',e.slug,'text',s.instruction,'label',s.link_label) order by s.position) from academy.category_guide_steps s join academy.entries e on e.id=s.entry_id where s.category_id=g.category_id)) from academy.category_guides g where category_id='08') is distinct from '{"title":"מהרצה ראשונה להבנת תשתית הסקה","intro":"מודל הוא המשקלים והמבנה; כלי ההרצה טוען אותו ומבצע הסקה. אפשר לצרוך שרת מקומי מתוך C# דרך HTTP בלי לשנות את הלוגיקה העסקית. אין צורך להתקין את כל הכלים.","note":"התרגילים הם תוכניות לימוד. לא הורדו מודלים ולא בוצעו ניסויי חומרה במסגרת הוספת הפרקים.","steps":[{"text":"התחל ב־Ollama לתרגול API מקומי, או ב־LM Studio אם נוח לך להתחיל בממשק חזותי.","slug":"ollama","label":"להרצה מקומית ולחיבור יישום"},{"text":"המשך ל־llama.cpp כדי להבין פורמט, כימות, זיכרון וחומרה. זהו מנוע נפרד ממשפחת Llama של Meta.","slug":"llama-cpp","label":"לשכבת המנוע והכימות"},{"text":"הכר vLLM לאחר מכן: שירות בקשות מקבילות, קיבולת ואחריות תפעולית. ההיכרות אינה מחייבת שרת GPU.","slug":"vllm","label":"להגשת מודלים ולתכנון עומס"}]}'::jsonb then raise exception 'Reviewed guide changed: 08'; end if;
end $$;
update academy.entries set revision=revision+1,verified_at='2026-11-03',revision_note='חבילת 07/08 מאושרת עם התאמות המשתמש; נוספו תיקונים, SDK/רישוי והבחנות תפעוליות. מקורות וסעיפים קודמים נשמרו. תרגילים לא הורצו.' where slug='llm-fundamentals';
update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: השוו חילוץ נתוני הזמנה בשני ספקים באותו schema ו־eval, כולל מקרים חסרים והזרקת הוראות.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='ידע מושגי; אינו SDK',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. משפחה, checkpoint, ספק ו־endpoint הם שכבות שונות. מכסת context כוללת קלט ופלט ולעיתים tokens להסקה; פלט JSON תקין אינו הרשאה לבצע פעולה.' where entry_id='llm-fundamentals';
update academy.catalog_facts set language_support_summary='ידע מושגי; אינו SDK',reviewed_at='2026-11-03' where entry_id='llm-fundamentals';
delete from academy.entry_language_labels where entry_id='llm-fundamentals';
update academy.learning_guidance set reviewed_at='2026-11-03' where entry_id='llm-fundamentals';
update academy.entries set revision=revision+1,verified_at='2026-11-03',revision_note='חבילת 07/08 מאושרת עם התאמות המשתמש; נוספו תיקונים, SDK/רישוי והבחנות תפעוליות. מקורות וסעיפים קודמים נשמרו. תרגילים לא הורצו.' where slug='openai-gpt';
update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: ממשו ב־ASP.NET Core חילוץ הזמנה באמצעות Responses ו־client .NET הרשמי, ואמתו JSON בצד השרת.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='C#/.NET — SDK רשמי; Python; JavaScript/TypeScript; HTTP',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. OpenAI מספקת client .NET רשמי. Responses הוא ממשק API, לא שם משפחת מודלים; יש להצמיד model ID ולבדוק תמיכת כלים, פלט מובנה ו־streaming לפי המודל והממשק.' where entry_id='openai-gpt';
update academy.catalog_facts set language_support_summary='C#/.NET — SDK רשמי; Python; JavaScript/TypeScript; HTTP',reviewed_at='2026-11-03' where entry_id='openai-gpt';
