update academy.entries set revision=revision+1,verified_at='2026-11-03',revision_note='חבילת 07/08 מאושרת עם התאמות המשתמש; נוספו תיקונים, SDK/רישוי והבחנות תפעוליות. מקורות וסעיפים קודמים נשמרו. תרגילים לא הורצו.' where slug='anthropic-claude';
update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: ממשו סיכום בקשת שירות דרך Messages ב־C#, כולל ביטול, טיפול בשגיאות ואישור אנושי לפני tool בעל תופעות לוואי.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='C#/.NET — SDK רשמי ל־Messages; Python; TypeScript; HTTP',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. קיים client C# רשמי ל־Messages. הוא נפרד מ־Claude Agent SDK ומהרצה דרך Bedrock או ענן אחר; אין להסיק parity של כל תכונה או הרשאות מכל שם SDK.' where entry_id='anthropic-claude';
