update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: בנו שירות .NET לחילוץ שדות ממסמך עם Google.GenAI, והשוו לאותו schema בספק אחר תוך תיעוד endpoint ומדיניות נתונים.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='C#/.NET — Google.GenAI רשמי; Python; JavaScript/TypeScript; HTTP',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. Google.GenAI הוא SDK רשמי ל־C#. Gemini API ונתיבי Google Cloud עשויים להשתמש ב־credentials, quotas ותנאים שונים; API key אינו שקול להרשאות IAM.' where entry_id='google-gemini';
