update academy.entries set revision=revision+1,verified_at='2026-11-03',revision_note='חבילת 07/08 מאושרת עם התאמות המשתמש; נוספו תיקונים, SDK/רישוי והבחנות תפעוליות. מקורות וסעיפים קודמים נשמרו. תרגילים לא הורצו.' where slug='deepseek';
update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: חברו HttpClient לאותו ממשק חילוץ קיים ובדקו שגיאות, streaming ותוצאת alias בפועל לפני החלפת ספק.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='HTTP; שימוש בלקוחות API תואמים — לא SDK C# מקומי מאומת',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. התיעוד מציג תאימות לפורמטים של OpenAI/Anthropic. alias עשוי להצביע על מודל אחר לאורך זמן; תאימות מבנה אינה הבטחת תמיכת כלים, reasoning או זהות SDK.' where entry_id='deepseek';
update academy.catalog_facts set language_support_summary='HTTP; שימוש בלקוחות API תואמים — לא SDK C# מקומי מאומת',reviewed_at='2026-11-03' where entry_id='deepseek';
