update academy.entries set revision=revision+1,verified_at='2026-11-03',revision_note='חבילת 07/08 מאושרת עם התאמות המשתמש; נוספו תיקונים, SDK/רישוי והבחנות תפעוליות. מקורות וסעיפים קודמים נשמרו. תרגילים לא הורצו.' where slug='meta-llama';
update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: בחרו checkpoint של Llama, קראו Model Card ורישיון, והגישו חילוץ JSON למערכת .NET דרך מנוע נתמך; תעדו זיכרון, כימות ומגבלות שימוש.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='תלוי במנוע ההרצה; C# דרך HTTP או runtime מתאים',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. Llama היא משפחת משקלים ולא SDK. Llama 4 Scout מופצת ברישיון Llama 4 מותאם; אין לתארה כ־Apache או MIT ואין להכליל תנאי checkpoint אחד לכל המשפחה. הבנת משקלים ורישוי נשארת חובה ללמוד.' where entry_id='meta-llama';
