update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: השוו Qwen3-8B ל־Llama או Gemma באותו תרחיש בעברית, מנוע וכימות, ותעדו רישיון ותנאי התאמה ללא דירוג איכות אוניברסלי.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='תלוי במנוע ההרצה; C# דרך HTTP או runtime מתאים',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. Qwen היא משפחה רחבה: Qwen3-8B הוא דוגמת checkpoint ברישיון Apache 2.0, ולא ראיה לרישיון אחיד לכל Qwen או שירות מסחרי. הבנת בחירת checkpoint ורישוי נשארת חובה ללמוד.' where entry_id='qwen';
