update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: שלבו API ב־ASP.NET Core דרך HTTP, תעדו מקור לקוח קהילתי אם נבחר, והשוו חילוץ נתונים וטעויות לאותו eval בספק אחר.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='Python ו־TypeScript — SDK רשמי; C# דרך HTTP או לקוח קהילתי מזוהה',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. רשימת SDK הרשמית מבחינה בלקוחות Python/TypeScript לעומת third-party. לא אומת SDK C# רשמי ייעודי. רישיון API מסחרי נפרד מרישיונות checkpoints זמינים.' where entry_id='mistral-ai';
