update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: בחרו Model Card ב־Hub, נמקו רישיון והתאמה, ואז בצעו תכנון בקשת HTTP דרך Provider מזוהה והשוו לשרת מקומי בלי להעביר נתונים רגישים.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='Python ו־JavaScript — לקוחות Providers; C# דרך HTTP',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. Hugging Face Hub וקריאת Model Cards הם בסיס חשוב מאוד ללמידה: רישיון, מגבלות, אופן אימון ושימוש. Inference Providers הוא שירות גישה נפרד, ו־Endpoints מסלול פריסה אחר; המדיניות תלויה גם בספק בפועל.' where entry_id='hugging-face';
