update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: נתבו חילוץ JSON בין ספקים מותרים בלבד, עם מגבלת עלות ותיעוד fallback; בדקו שדרישת פרטיות נשמרת גם בתקלה.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='HTTP; לקוחות API תואמים',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. נתב מאחד גישה אך provider selection, fallback ו־data collection הם חלק מהחוזה. הגבלת ספקים ודרישת תכונות צריכות להיות מפורשות; תעדו ספק ודגם בפועל ואל תניחו שכל fallback משמר יכולות.' where entry_id='openrouter';
