update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: השוו על הנייר תרחיש חילוץ עומס משתנה ב־serverless לעומת dedicated, עם עלות, פרטיות, רישיון משקלים ודרישות זמינות.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='Python ו־TypeScript; C# דרך HTTP',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. Serverless ו־Dedicated אינם אותו מוצר תפעולי. מדיניות פרטיות, אימון ושמירה ו־ZDR תלויות מוצר ותצורה; אין הבטחת אי־שמירה גורפת לכל בקשה.' where entry_id='together-ai';
