update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: תכננו שירות ASP.NET Core עם Entra, זהות מנוהלת והרשאות מינימליות; ערכו מטריצת endpoint, חבילת SDK, model ID ויכולות מאומתות.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='C#/.NET — SDK לפי שירות ו־endpoint; HTTP',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. בחרו SDK לפי endpoint: לקוח פרויקט Foundry לניהול משאבי פרויקט; לקוח OpenAI עבור מסלול OpenAI v1; לקוח Anthropic עבור מסלולו. אין לקוח יחיד שמבטיח כל יכולת. לא פורסם תאריך פרישה ל־SDK כי לא אומת מחדש. Foundry עצמה אינה מסומנת Legacy.' where entry_id='microsoft-foundry';
