update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: תכננו שירות .NET עם project, region, IAM ו־quotas מפורשים; השוו Gemini API ישיר לנתיב ארגוני בלי להניח תנאי פרטיות או חיוב זהים.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='C#/.NET — לפי שירות Google Cloud; HTTP ו־Google.GenAI לפי endpoint',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. Gemini Enterprise Agent Platform מוצגת לצד השם המוכר Vertex AI; זהו מסלול ענן עם מודלים מנוהלים ופריסה לפי מוצר, לא משפחת משקלים חדשה ולא הבטחת פריסה עצמית לכל מודל. ה־slug נשמר.' where entry_id='google-vertex-ai';
