update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: תכננו סיכום קריאת שירות דרך Converse ב־.NET עם הרשאת IAM מינימלית, model ID ואזור מפורשים, וחסימת פעולה לפני אישור משתמש.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='C#/.NET — AWS SDK for .NET v4; HTTP',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. AWS SDK for .NET v4 כולל דוגמאות Bedrock Runtime ו־Converse. IAM, region ומטריצת יכולות המודל קובעים גישה; Converse אינו מבטיח שכל מודל תומך באותם כלים או פורמטים.' where entry_id='amazon-bedrock';
