update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: חברו ASP.NET Core לשרת מקומי לחילוץ נתוני פנייה; תעדו מיקום משקלים, endpoint ותעבורה החוצה, עם timeout ו־schema validation.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='HTTP; Python ו־JavaScript — SDK רשמי; C# דרך HTTP',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. Ollama מפשטת הורדה והרצה, ומציעה גם מסלולי cloud: אין להציג כל שימוש כאוטומטית מקומי. API מקומי אינו דורש אימות כברירת מחדל; אין לחשוף port לרשת בלתי מהימנה. קוד runtime ומשקלים כפופים לרישיונות נפרדים.' where entry_id='ollama';
