update academy.entries set revision=revision+1,verified_at='2026-11-03',revision_note='חבילת 07/08 מאושרת עם התאמות המשתמש; נוספו תיקונים, SDK/רישוי והבחנות תפעוליות. מקורות וסעיפים קודמים נשמרו. תרגילים לא הורצו.' where slug='lm-studio';
update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: הכינו תהליך headless עם llmster וחיבור .NET דרך HTTP; בחרו מודל, בדקו אימות, bind address וזמינות offline לפני חיבור לנתוני אמת.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='Python ו־TypeScript — SDK; C# דרך HTTP',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. LM Studio כוללת API ו־llmster להרצה headless ולא רק GUI. אימות API זמין כאפשרות מ־0.4 ומעלה; יש להפעילו במפורש לפי התצורה. עבודה offline מותנית בהורדת המודלים ובמסלול שנבחר.' where entry_id='lm-studio';
