update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: הריצו ניסוי מתוכנן באותו checkpoint בשני כימותים, ותעדו peak memory, latency ודיוק חילוץ לפני בחירת פורמט לשירות .NET.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='C/C++; שרת HTTP ל־C# ושפות נוספות',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. llama.cpp הוא מנוע עם שרת ולא משפחת Llama. GGUF וכימות משנים זיכרון ואיכות; batching ופלט מובנה דורשים בדיקה לפי השרת והמודל. schema תקין אינו בדיקת אמת או הרשאה.' where entry_id='llama-cpp';
