update academy.entries set revision=revision+1,verified_at='2026-11-03',revision_note='חבילת 07/08 מאושרת עם התאמות המשתמש; נוספו תיקונים, SDK/רישוי והבחנות תפעוליות. מקורות וסעיפים קודמים נשמרו. תרגילים לא הורצו.' where slug='vllm';
update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: תכננו ניסוי batching ועומס מול SGLang באותו מודל וחומרה; בדקו auth לכל נתיב חשוף, תקרת concurrency, זיכרון ותוכנית rollback.',exercise='בנו תוכנית בדיקה חוזרת לתרחיש: schema, קלט חסר, שגיאות, timeout, עלות ונתוני זיהוי המודל/endpoint. הפרידו איכות תשובה מהרשאת פעולה ותעדו מה לא נבדק בפועל.',language_support_note='Python; שרת HTTP ל־C# ושפות נוספות',alternatives_note='השוו את החלופות המקושרות באותו תרחיש ובאותן מגבלות. העדיפו מסלול אחד לעומק; SDK רשמי, HTTP או מנוע מקומי אינם תחליפים זהים. vLLM הוא מנוע serving. יש להצמיד תמיכת חומרה, backend ותלויות לגרסה שנבדקת. api-key אינו מגן בהכרח על כל נתיבי השרת; נדרשים גבול רשת ומדיניות endpoint. תג v0.33.0rc3 סותר תיאור release מסוים ולכן אין כאן טענה לגרסה יציבה.' where entry_id='vllm';
