update academy.category_guides set title='איך ללמוד מודלים, ספקי API ופלטפורמות?',introduction='התחילו בהבדל בין משפחת מודלים, checkpoint, ספק ו־endpoint. תרגלו ספק API אחד לעומק והשוו שני רק באותו eval. אחר כך בחרו משפחת משקלים אחת, נתב או ענן לפי הצורך. הסדר פדגוגי ואינו דירוג איכות או נתח שוק.',note='Llama ו־Qwen נשארות חובה ללמוד לפי החלטת העריכה. HF Hub וקריאת Model Cards הם יסוד חשוב מאוד; Inference Providers כדאי להכיר. Gemma, Phi ו־Command משלימות השוואה ואינן חובה להרצה. דוגמאות לא הורצו; אין תאריכי פרישה או גרסה יציבה שלא אומתו.' where category_id='07';delete from academy.category_guide_steps where category_id='07';
update academy.category_guides set title='מיסודות inference להרצה ול־serving',introduction='למדו את שרשרת ההרצה: checkpoint → runtime → server → gateway → client. בחרו כלי התחלה אחד; עברו לתפעול GPU או gateway רק כשהצורך ברור. מודל קטן או מקומי אינו הבטחת איכות, פרטיות או היעדר תעבורה החוצה.',note='תרגילים מתוכננים ולא הורצו. C# ב־ONNX Runtime GenAI הוא Preview. גרסת vLLM לא מסומנת יציבה. רישיון מנוע נפרד מרישיון המשקלים; בדקו תמיכת מודל וחומרה לפי הגרסה המוצמדת.' where category_id='08';delete from academy.category_guide_steps where category_id='08';
